    pub struct App {
        pub definition: AppDefinition,
        pub examples: Vec<ExampleDefinition>,
    }

    impl App {
        pub async fn builder(id: impl Into<String>, label: impl Into<LocalizedLabel>) -> AppBuilder {
            AppBuilder::new(id, label).await
        }

        /// 🗂️ Resource kinds declared via `.artifact_kind(...)` — see `AppDefinition.artifact_kinds`
        /// (round-trips through the plugin manifest; `semio_framework_os`'s artifact catalog registry
        /// consumes it from there at plugin registration time).
        pub async fn from_builder(builder: AppBuilder) -> Self {
            Self { definition: builder.build_definition(), examples: Vec::new() }
        }

        /// 🧷️ Fallible twin of `from_builder` — see `AppBuilder::try_build_definition`.
        pub async fn try_from_builder(builder: AppBuilder) -> Result<Self, PluginAssemblyError> {
            Ok(Self { definition: builder.try_build_definition()?, examples: Vec::new() })
        }

        /// 📚️ Registers an example from a definition-leaf [`ExampleSource`] (canonical path).
        pub async fn example_source(mut self, source: impl Into<ExampleSource>) -> Self {
            self.examples.push(ExampleDefinition::from(source.into()));
            self
        }

        /// 📚️ Registers an example by restating id/label/payload/icon.
        /// Prefer [`Self::example_source`] once the definition leaf owns those fields; kept so
        /// existing `create_*_app()` call sites keep compiling during the example-shape migration.
        pub async fn example(self, id: impl Into<String>, label: impl Into<LocalizedLabel>, document_json: impl Into<String>, icon_id: impl Into<IconName>) -> Self {
            self.example_source(ExampleSource::new(id, label, document_json, icon_id)).await
        }

        /// 🚧️ B1 stub: `WorkflowDefinition` + `PluginManifest.workflows` were deleted from framework-core
        /// (WP-0.1, concurrent) — real workflow-palette derivation moves to `register_app_io`/
        /// `workflow_palette()` in Wave 1 (`AppIo`-driven, not this free-text `yields`). Kept as a no-op
        /// so the ~50 existing `.workflow(...)` call sites across every app manifest keep compiling
        /// unchanged until their own wave touches them.
        pub async fn workflow(self, _workflow_step_id: impl Into<String>, _label: impl Into<String>, _yields: impl Into<String>) -> Self {
            self
        }
    }

    //#region 🔖️DocumentContract
    /// @emoji 🧾️ Read-only view of an app's document handed to `ArtifactApp::handle_action`/`render`:
    /// the materialized snapshot plus the history metadata (checkpoints/alternatives/undo state)
    /// derived from the owning {@link VcsArtifactApp}'s persistent {@link ArtifactStore}.
    pub struct ArtifactView<'a, P> {
        pub snapshot: &'a P,
        pub history: &'a HistoryView,
        /// 🧸️ Read access to this document's OWNED CHILDREN, each of which is its own envelope with
        /// its own `ArtifactVcs` history (never an inline subtree). See {@link ChildContentView}.
        pub children: ChildContentView,
        operation: Option<AppOperationContext>,
        render_operation: Option<AppRenderOperationContext>,
        snapshot_read: std::sync::Mutex<Option<store::SnapshotRead<P>>>,
    }

    /// 🪪️ Durable authority captured once at public command admission and copied into every
    /// plugin continuation record.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct AppOperationContext {
        pub app_instance_id: u32,
        pub parent_document_id: String,
        pub operation_id: u64,
        pub generation: u64,
        pub canonical_base_revision: [u8; 32],
    }

    /// 🎨️ Fixed authority for one live renderer-observed document revision. Unlike a command
    /// operation, this carries no user invocation id: it binds an app-owned retained background job to
    /// the exact instance, base revision and store generation observed by the renderer/refresh pass.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct AppRenderOperationContext {
        pub app_instance_id: u32,
        pub base_revision: semio_framework_job::RevisionId,
        pub generation: semio_framework_job::Generation,
        pub canonical_base_revision: [u8; 32],
    }

    impl AppOperationContext {
        /// 🧬️ Fixed-width lowercase encoding for typed persisted continuation fields.
        pub fn canonical_base_revision_hex(&self) -> String {
            const HEX: &[u8; 16] = b"0123456789abcdef";
            let mut result = String::with_capacity(64);
            for byte in self.canonical_base_revision {
                result.push(HEX[usize::from(byte >> 4)] as char);
                result.push(HEX[usize::from(byte & 0x0f)] as char);
            }
            result
        }
    }

    impl<'a, P> ArtifactView<'a, P> {
        /// 🏗️ A view over a document with no composed children — the overwhelming majority, and the
        /// shape every leaf app and test uses. Prefer this over a struct literal: lane views grow
        /// over time, and a constructor absorbs that growth without touching every call site.
        pub fn new(snapshot: &'a P, history: &'a HistoryView) -> Self {
            Self { snapshot, history, children: ChildContentView::EMPTY, operation: None, render_operation: None, snapshot_read: std::sync::Mutex::new(None) }
        }

        /// 🪪️ Synchronous retained-worker view bound to one exact admitted operation.
        pub fn with_operation(snapshot: &'a P, history: &'a HistoryView, operation: AppOperationContext) -> Self {
            Self { snapshot, history, children: ChildContentView::EMPTY, operation: Some(operation), render_operation: None, snapshot_read: std::sync::Mutex::new(None) }
        }

        /// 🧩️ App-side composing view for retained command work, which observes its children through
        /// [`ArtifactOwnedToolJobContext::children`] rather than through a host render pass and so
        /// carries no render identity. Synchronous on purpose: it only moves owned fields.
        pub fn with_children(snapshot: &'a P, history: &'a HistoryView, children: ChildContentView) -> Self {
            Self { snapshot, history, children, operation: None, render_operation: None, snapshot_read: std::sync::Mutex::new(None) }
        }

        /// 🏗️ A view over a composing document, wired to its live child stores AND to the identity the
        /// live revision is observed under. Every host entry point that hands an app a composing view —
        /// `render`, `pending_effects`, `window_engagements`, `window_measures`, `tool_measures`,
        /// `context_menu`, `interaction_topology`, `export_media`, `media_fingerprint` — goes through
        /// here, so [`ArtifactView::render_operation`] is total on the host and an app that leases a
        /// per-instance session off it (puzzle 3d's `puzzle3d_view_session_key`) never runs cold.
        async fn with_render_context(snapshot: &'a P, history: &'a HistoryView, children: ChildContentView, render_operation: AppRenderOperationContext, snapshot_read: Option<store::SnapshotRead<P>>) -> Self {
            Self { snapshot, history, children, operation: None, render_operation: Some(render_operation), snapshot_read: std::sync::Mutex::new(snapshot_read) }
        }

        /// 🪪️ Returns the actual public job authority for command handlers.
        pub fn operation(&self) -> Result<&AppOperationContext, Fault> {
            self.operation.as_ref().ok_or_else(|| plugin_sdk_fault("the artifact view is not bound to a public command operation"))
        }

        /// 🪪️ Optional form for render/test-only views which do not enter command authority.
        pub fn operation_optional(&self) -> Option<&AppOperationContext> {
            self.operation.as_ref()
        }

        /// 🎨️ Returns the immutable identity observed by a live render/refresh pass.
        pub fn render_operation(&self) -> Option<AppRenderOperationContext> {
            self.render_operation
        }

        /// 🧵️ Transfers the one registered immutable snapshot-read lease to a retained worker
        /// owner. Contention and a second take fail closed without cloning the underlying snapshot.
        pub fn take_snapshot_read(&self) -> Result<store::SnapshotRead<P>, Fault> {
            let mut owner = self.snapshot_read.try_lock().map_err(|_| plugin_sdk_fault("the live snapshot-read lease is busy"))?;
            owner.take().ok_or_else(|| plugin_sdk_fault("the artifact view has no transferable live snapshot-read lease"))
        }
    }

    /// @emoji 🧸️ Read-only access to a composing document's live child stores, keyed `(slot,
    /// child_id)` exactly as the parent's `ArtifactChild` handles name them.
    ///
    /// This is the seam that replaces the `thread_local!`/session `HashMap<child_id, content>`
    /// caches every composed plugin used to carry. Those caches went STALE the moment anything
    /// moved a child's history without going through `ArtifactApp::handle` — store-level undo/redo
    /// and checkout do exactly that. `new` clones every live `SpaceMember`'s already-owned snapshot
    /// `Arc` and fixed-size revision ONCE, without encoding or graph cloning, so a view built fresh
    /// immediately before each `handle`/`render` call (as every {@link VcsArtifactApp} call site
    /// does) cannot present state older than the dispatch it belongs to.
    ///
    /// 🚫️async: E1-adjacent by construction, not tagged — `M: SpaceMember` is generic on {@link
    /// Self::new} itself, NOT on this struct. `ArtifactApp::render`/`handle`/… fix their `doc`
    /// parameter's type at exactly `ArtifactView<'_, Self::Snapshot>` (no member-kind parameter),
    /// so `ChildContentView` must stay a single, non-generic, dyn-free type usable from EVERY
    /// plugin's fixed trait-method signature — the old `Box<dyn SpaceMember>` erasure existed
    /// precisely to buy that uniformity, which is no longer available once `SpaceMember` is AFIT
    /// (not object-safe). Pre-extracting each child's immutable snapshot handle at `new()` time (function-generic
    /// over the caller's concrete `M`) reproduces the same uniformity without a trait object or a
    /// fleet-wide `ArtifactApp::Members` associated-type rollout — see
    /// `📓️terra-dedyn-fw-os-spacemember-report.md` §ChildContentView for the rejected alternatives.
    /// `Default` (`EMPTY`) so a leaf app's view costs nothing and needs no ceremony.
    const CHILD_CONTENT_SLOTS: usize = 1_024;
    const CHILD_CONTENT_PAGE_SLOTS: usize = 32;
    const CHILD_CONTENT_PAGES: usize = CHILD_CONTENT_SLOTS / CHILD_CONTENT_PAGE_SLOTS;
    const CHILD_CONTENT_ID_BYTES: usize = 256;
    const OWNED_DOCUMENT_MEMBER_PREPARATION_BYTES: usize = store::MEMBER_OPEN_IDENTITY_BYTES * 8;

    pub(crate) struct ChildMemberEntry<M> {
        pub(crate) reference: ArtifactRef,
        pub(crate) owner: store::OwnerRef,
        pub(crate) member: M,
    }

    struct ChildMemberAdmission {
        index: usize,
        generation: u64,
    }

    pub struct ChildMemberRegistrationError<M> {
        pub member: Option<M>,
        pub fault: Fault,
    }

    impl<M> std::fmt::Debug for ChildMemberRegistrationError<M> {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter.debug_struct("ChildMemberRegistrationError").field("owner_returned", &self.member.is_some()).field("fault", &self.fault).finish()
        }
    }

    pub(crate) struct ChildMemberRegistry<M> {
        slots: Box<[std::mem::MaybeUninit<ChildMemberEntry<M>>]>,
        occupied: [u64; CHILD_CONTENT_SLOTS / 64],
        reserved: [u64; CHILD_CONTENT_SLOTS / 64],
        generations: [u64; CHILD_CONTENT_SLOTS],
        dense_slots: [usize; CHILD_CONTENT_SLOTS],
        ordinal_by_slot: [usize; CHILD_CONTENT_SLOTS],
        next_generation: u64,
        len: usize,
        allocation_admitted: bool,
    }

    impl<M> ChildMemberRegistry<M> {
        fn new() -> Self {
            let mut slots = Vec::new();
            let allocation_admitted = slots.try_reserve_exact(CHILD_CONTENT_SLOTS).is_ok();
            if allocation_admitted {
                slots.resize_with(CHILD_CONTENT_SLOTS, std::mem::MaybeUninit::uninit);
            }
            Self {
                slots: slots.into_boxed_slice(),
                occupied: [0; CHILD_CONTENT_SLOTS / 64],
                reserved: [0; CHILD_CONTENT_SLOTS / 64],
                generations: [0; CHILD_CONTENT_SLOTS],
                dense_slots: [usize::MAX; CHILD_CONTENT_SLOTS],
                ordinal_by_slot: [usize::MAX; CHILD_CONTENT_SLOTS],
                next_generation: 0,
                len: 0,
                allocation_admitted,
            }
        }

        fn hash(slot: &str, child_id: &str) -> Result<usize, Fault> {
            ChildContentView::hash(slot, child_id)
        }

        fn occupied(&self, index: usize) -> bool {
            self.occupied[index / 64] & (1 << (index % 64)) != 0
        }

        fn reserved(&self, index: usize) -> bool {
            self.reserved[index / 64] & (1 << (index % 64)) != 0
        }

        fn entry(&self, index: usize) -> Option<&ChildMemberEntry<M>> {
            self.occupied(index).then(|| unsafe { self.slots[index].assume_init_ref() })
        }

        fn entry_mut(&mut self, index: usize) -> Option<&mut ChildMemberEntry<M>> {
            if !self.occupied(index) {
                return None;
            }
            Some(unsafe { self.slots[index].assume_init_mut() })
        }

        fn locate(&self, slot: &str, child_id: &str) -> Result<Result<usize, usize>, Fault> {
            if !self.allocation_admitted {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-allocation"), "fixed child-member registry allocation was not pre-admitted"));
            }
            let start = Self::hash(slot, child_id)?;
            for offset in 0..CHILD_CONTENT_SLOTS {
                let index = (start + offset) % CHILD_CONTENT_SLOTS;
                match self.entry(index) {
                    Some(candidate) if candidate.owner.slot == slot && candidate.reference.artifact_id == child_id => return Ok(Ok(index)),
                    Some(_) => {}
                    None if self.reserved(index) => {}
                    None => return Ok(Err(index)),
                }
            }
            Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-capacity"), "fixed child-member registry is saturated"))
        }

        fn admit_identity(&mut self, slot: &str, child_id: &str) -> Result<ChildMemberAdmission, Fault> {
            if !self.allocation_admitted {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-allocation"), "fixed child-member registry allocation was not pre-admitted"));
            }
            match self.locate(slot, child_id)? {
                Ok(_) => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-duplicate"), "fixed child-member identity is already occupied")),
                Err(index) => {
                    let generation = self.next_generation.checked_add(1).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-generation"), "fixed child-member admission generation exhausted"))?;
                    self.next_generation = generation;
                    self.generations[index] = generation;
                    self.reserved[index / 64] |= 1 << (index % 64);
                    Ok(ChildMemberAdmission { index, generation })
                }
            }
        }

        fn admit(&mut self, key: &(String, String)) -> Result<ChildMemberAdmission, Fault> {
            self.admit_identity(&key.0, &key.1)
        }

        #[expect(clippy::needless_pass_by_value, reason = "This non-Copy token conveys one-use admission authority and must be consumed by the commit, even though its identity fields are scalar.")]
        fn insert_admitted(&mut self, admission: ChildMemberAdmission, reference: ArtifactRef, owner: store::OwnerRef, member: M) {
            assert!(self.reserved(admission.index) && self.generations[admission.index] == admission.generation && !self.occupied(admission.index), "exact child-member admission changed while its exclusive app owner was suspended");
            assert!(owner.child_id == reference.artifact_id, "child-member owner and reference must retain the same exact child identity");
            self.reserved[admission.index / 64] &= !(1 << (admission.index % 64));
            self.slots[admission.index].write(ChildMemberEntry { reference, owner, member });
            self.occupied[admission.index / 64] |= 1 << (admission.index % 64);
            self.dense_slots[self.len] = admission.index;
            self.ordinal_by_slot[admission.index] = self.len;
            self.len += 1;
        }

        pub(crate) fn get(&self, key: &(String, String)) -> Option<&ChildMemberEntry<M>> {
            let Ok(Ok(index)) = self.locate(&key.0, &key.1) else { return None };
            self.entry(index)
        }

        pub(crate) fn get_mut(&mut self, key: &(String, String)) -> Option<&mut ChildMemberEntry<M>> {
            let Ok(Ok(index)) = self.locate(&key.0, &key.1) else { return None };
            self.entry_mut(index)
        }

        fn entries(&self) -> impl Iterator<Item = &ChildMemberEntry<M>> {
            self.dense_slots[..self.len].iter().map(|index| self.entry(*index).expect("dense child-member slot remains occupied"))
        }

        fn entries_physical(&self) -> impl Iterator<Item = &ChildMemberEntry<M>> {
            let occupied = self.occupied;
            self.slots
                .iter()
                .enumerate()
                .filter(move |(index, _)| occupied[*index / 64] & (1 << (*index % 64)) != 0)
                .map(|(_, slot)| unsafe { slot.assume_init_ref() })
        }

        fn entries_mut_physical(&mut self) -> impl Iterator<Item = &mut ChildMemberEntry<M>> {
            let occupied = self.occupied;
            self.slots
                .iter_mut()
                .enumerate()
                .filter_map(move |(index, slot)| (occupied[index / 64] & (1 << (index % 64)) != 0).then(|| unsafe { slot.assume_init_mut() }))
        }

        fn entry_by_ordinal(&self, ordinal: usize) -> Option<&ChildMemberEntry<M>> {
            (ordinal < self.len).then(|| self.entry(self.dense_slots[ordinal]).expect("dense child-member slot remains occupied"))
        }

        fn take_at(&mut self, index: usize) -> Option<ChildMemberEntry<M>> {
            if !self.occupied(index) {
                return None;
            }
            self.occupied[index / 64] &= !(1 << (index % 64));
            self.len -= 1;
            let ordinal = self.ordinal_by_slot[index];
            let moved = self.dense_slots[self.len];
            self.dense_slots[ordinal] = moved;
            self.ordinal_by_slot[moved] = ordinal;
            self.dense_slots[self.len] = usize::MAX;
            self.ordinal_by_slot[index] = usize::MAX;
            Some(unsafe { self.slots[index].assume_init_read() })
        }

        fn cancel_admission(&mut self, admission: &ChildMemberAdmission) -> bool {
            if !self.reserved(admission.index) || self.generations[admission.index] != admission.generation {
                return false;
            }
            self.reserved[admission.index / 64] &= !(1 << (admission.index % 64));
            true
        }

        fn len(&self) -> usize {
            self.len
        }

        fn is_empty(&self) -> bool {
            self.len == 0
        }
    }

    impl<M> Drop for ChildMemberRegistry<M> {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.is_empty(), "fixed child-member registry reached Drop before every exact member was transferred to bounded retirement");
            assert!(std::thread::panicking() || self.reserved.iter().all(|word| *word == 0), "fixed child-member registry reached Drop with a reserved owner slot outside exact admission");
            assert!(std::thread::panicking() || self.dense_slots.iter().all(|slot| *slot == usize::MAX) && self.ordinal_by_slot.iter().all(|ordinal| *ordinal == usize::MAX), "fixed child-member registry reached Drop with a stale dense owner coordinate");
        }
    }

    /// 📥️ Retains one exact recursive member identity with its admitted bounded open request.
    pub struct OwnedDocumentMemberIngress {
        identity: std::mem::ManuallyDrop<Option<(usize, ArtifactRef, store::OwnerRef)>>,
        request: std::mem::ManuallyDrop<Option<store::MemberOpenRequest>>,
        identity_field: u8,
    }

    impl OwnedDocumentMemberIngress {
        /// 🪪️ Binds one closure ordinal and recursive owner to the request's sealed identity.
        #[expect(clippy::result_large_err, reason = "Rejected ingress returns its exact retained page and identity owners unchanged.")]
        pub fn try_new(
            ordinal: usize,
            reference: ArtifactRef,
            owner: store::OwnerRef,
            request: store::MemberOpenRequest,
        ) -> Result<Self, (Fault, Self)> {
            let ingress = Self {
                identity: std::mem::ManuallyDrop::new(Some((ordinal, reference, owner))),
                request: std::mem::ManuallyDrop::new(Some(request)),
                identity_field: 0,
            };
            let (_, reference, owner) = ingress.identity.as_ref().expect("fresh member ingress retains identity");
            let request = ingress.request.as_ref().expect("fresh member ingress retains request");
            let valid = ordinal < store::OWNED_DOCUMENT_MAXIMUM_MEMBERS
                && request.admitted_expected().is_ok()
                && request.expected() == reference
                && request.owner() == Some(owner)
                && owner.child_id == reference.artifact_id;
            if valid {
                Ok(ingress)
            } else {
                Err((plugin_sdk_fault("owned document member ingress identity, owner, ordinal, or admitted request does not match"), ingress))
            }
        }

        fn ordinal(&self) -> usize {
            self.identity.as_ref().expect("live member ingress retains identity").0
        }

        fn operation(&self) -> semio_framework_job::OperationId {
            self.request.as_ref().expect("live member ingress retains request").operation()
        }

        fn generation(&self) -> semio_framework_job::Generation {
            self.request.as_ref().expect("live member ingress retains request").generation()
        }

        fn take_request(&mut self) -> Option<store::MemberOpenRequest> {
            self.request.take()
        }

        fn has_request(&self) -> bool {
            self.request.is_some()
        }

        fn return_request(&mut self, request: store::MemberOpenRequest) {
            assert!(self.request.is_none(), "member ingress request can only return to its exact empty slot");
            *self.request = Some(request);
        }

        fn take_identity(&mut self) -> Option<(usize, ArtifactRef, store::OwnerRef)> {
            self.identity.take()
        }

        fn has_identity(&self) -> bool {
            self.identity.is_some()
        }

        fn identity_string_mut(&mut self) -> Option<&mut String> {
            let (_, reference, owner) = self.identity.as_mut()?;
            match self.identity_field {
                0 => Some(&mut reference.artifact_id),
                1 => Some(&mut reference.dialect.artifact_kind),
                2 => Some(&mut reference.dialect.standard),
                3 => Some(&mut reference.dialect.subset),
                4 => Some(&mut owner.parent.artifact_id),
                5 => Some(&mut owner.parent.dialect.artifact_kind),
                6 => Some(&mut owner.parent.dialect.standard),
                7 => Some(&mut owner.parent.dialect.subset),
                8 => Some(&mut owner.slot),
                9 => Some(&mut owner.child_id),
                _ => None,
            }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(request) = self.request.as_mut() {
                return match request.close_step(1, maximum_bytes).map_err(plugin_sdk_fault)? {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= 1 && released_bytes <= maximum_bytes => {
                        Ok(PluginCloseStep::Pending { released_items, released_bytes })
                    }
                    store::SnapshotRetirementStep::Pending { .. } => Err(plugin_sdk_fault("member ingress request exceeded its close grant")),
                    store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "member ingress request retirement is blocked" }),
                    store::SnapshotRetirementStep::Complete if request.terminal_is_empty() => {
                        drop(self.request.take());
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    store::SnapshotRetirementStep::Complete => Err(plugin_sdk_fault("member ingress request returned false terminal")),
                };
            }
            while self.identity_field < 10 && self.identity_string_mut().is_some_and(|field| field.is_empty()) {
                self.identity_field += 1;
            }
            if let Some(field) = self.identity_string_mut() {
                let bytes = field.chars().next_back().map_or(0, char::len_utf8);
                if bytes > maximum_bytes {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                field.pop();
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: bytes });
            }
            if let Some(identity) = self.identity.take() {
                drop(identity);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(PluginCloseStep::Complete)
        }

        fn terminal_is_empty(&self) -> bool {
            self.identity.is_none() && self.request.is_none()
        }
    }

    impl Drop for OwnedDocumentMemberIngress {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.terminal_is_empty(), "owned document member ingress reached Drop before exact handoff or bounded close");
        }
    }

    struct OwnedDocumentMemberIngressRegistry {
        slots: Box<[std::mem::MaybeUninit<OwnedDocumentMemberIngress>]>,
        occupied: [u64; CHILD_CONTENT_SLOTS / 64],
        expected: usize,
        len: usize,
        generation: u64,
        sealed: bool,
        close_cursor: usize,
        close_active: std::mem::ManuallyDrop<Option<OwnedDocumentMemberIngress>>,
    }

    impl OwnedDocumentMemberIngressRegistry {
        fn try_new(expected: usize) -> Result<Self, Fault> {
            if expected > store::OWNED_DOCUMENT_MAXIMUM_MEMBERS {
                return Err(plugin_sdk_fault("owned document member ingress exceeds the recursive closure member limit"));
            }
            let mut slots = Vec::new();
            slots.try_reserve_exact(expected).map_err(|_| plugin_sdk_fault("owned document member ingress allocation was not admitted"))?;
            slots.resize_with(expected, std::mem::MaybeUninit::uninit);
            Ok(Self {
                slots: slots.into_boxed_slice(),
                occupied: [0; CHILD_CONTENT_SLOTS / 64],
                expected,
                len: 0,
                generation: 0,
                sealed: false,
                close_cursor: 0,
                close_active: std::mem::ManuallyDrop::new(None),
            })
        }

        #[expect(clippy::result_large_err, reason = "Refusal returns the exact retained member ingress owner unchanged.")]
        fn admit(&mut self, ingress: OwnedDocumentMemberIngress) -> Result<(), (Fault, OwnedDocumentMemberIngress)> {
            let ordinal = ingress.ordinal();
            if self.sealed || ordinal >= self.expected || self.occupied[ordinal / 64] & (1 << (ordinal % 64)) != 0 {
                return Err((plugin_sdk_fault("owned document member ingress is sealed, out of range, or duplicates an ordinal"), ingress));
            }
            let Some(generation) = self.generation.checked_add(1) else {
                return Err((plugin_sdk_fault("owned document member ingress generation exhausted"), ingress));
            };
            self.slots[ordinal].write(ingress);
            self.occupied[ordinal / 64] |= 1 << (ordinal % 64);
            self.len += 1;
            self.generation = generation;
            Ok(())
        }

        fn seal(&mut self) -> Result<(), Fault> {
            if self.sealed || self.len != self.expected {
                return Err(plugin_sdk_fault("owned document member ingress is duplicate-sealed or incomplete"));
            }
            self.sealed = true;
            Ok(())
        }

        fn take(&mut self, ordinal: usize) -> Option<OwnedDocumentMemberIngress> {
            if ordinal >= self.expected || self.occupied[ordinal / 64] & (1 << (ordinal % 64)) == 0 {
                return None;
            }
            self.occupied[ordinal / 64] &= !(1 << (ordinal % 64));
            self.len -= 1;
            Some(unsafe { self.slots[ordinal].assume_init_read() })
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if let Some(active) = self.close_active.as_mut() {
                let step = active.close_step(maximum_items, maximum_bytes)?;
                if step == PluginCloseStep::Complete {
                    if !active.terminal_is_empty() {
                        return Err(plugin_sdk_fault("member ingress close returned false terminal"));
                    }
                    drop(self.close_active.take());
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            while self.close_cursor < self.expected {
                let ordinal = self.close_cursor;
                self.close_cursor += 1;
                if let Some(ingress) = self.take(ordinal) {
                    *self.close_active = Some(ingress);
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
            }
            Ok(PluginCloseStep::Complete)
        }

        fn terminal_is_empty(&self) -> bool {
            self.len == 0 && self.close_active.is_none()
        }
    }

    impl Drop for OwnedDocumentMemberIngressRegistry {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.terminal_is_empty(), "owned document member ingress registry reached Drop before every request owner was handed off or bounded-closed");
        }
    }

    struct DocumentClosureSourceView<'a, P, M> {
        generation: u64,
        root_reference: &'a ArtifactRef,
        root_snapshot: &'a P,
        members: &'a ChildMemberRegistry<M>,
    }

    impl<'a, P, M> DocumentClosureSourceView<'a, P, M> {
        fn new(generation: u64, root_reference: &'a ArtifactRef, root_snapshot: &'a P, members: &'a ChildMemberRegistry<M>) -> Self {
            Self { generation, root_reference, root_snapshot, members }
        }
    }

    impl<P, M> store::OwnedDocumentClosureSource for DocumentClosureSourceView<'_, P, M>
    where
        P: semio_framework_schema::ArtifactCompositionFields,
        M: SpaceMember,
    {
        fn generation(&self) -> u64 {
            self.generation
        }

        fn root_reference(&self) -> &ArtifactRef {
            self.root_reference
        }

        fn member_count(&self) -> usize {
            self.members.len()
        }

        fn member_reference(&self, index: usize) -> Option<&ArtifactRef> {
            self.members.entry_by_ordinal(index).map(|entry| &entry.reference)
        }

        fn member_owner(&self, index: usize) -> Option<&store::OwnerRef> {
            self.members.entry_by_ordinal(index).map(|entry| &entry.owner)
        }

        fn child_projection(&self, parent: Option<usize>) -> Result<store::ChildRestoreProjection<'_>, store::ChildRestoreProjectionError> {
            match parent {
                None => store::ChildRestoreProjection::from_snapshot(self.root_snapshot),
                Some(index) => self
                    .members
                    .entry_by_ordinal(index)
                    .ok_or(store::ChildRestoreProjectionError::IncompleteSet)?
                    .member
                    .child_restore_projection(),
            }
        }
    }

    #[cfg(test)]
    include!("🧪️tests/🔬️app-child-member-registry/🦀️.rs");

    pub(crate) struct ChildContentEntry {
        slot: String,
        child_id: String,
        dialect: ArtifactDialect,
        revision: [u8; 32],
        pub(crate) snapshot: store::ErasedSnapshotRead,
    }

    #[derive(Clone)]
    struct ChildContentPage {
        entries: [Option<std::sync::Arc<ChildContentEntry>>; CHILD_CONTENT_PAGE_SLOTS],
    }

    impl Default for ChildContentPage {
        fn default() -> Self {
            Self { entries: std::array::from_fn(|_| None) }
        }
    }

    #[derive(Clone)]
    pub(crate) struct ChildContentRoot {
        pages: [Option<std::sync::Arc<ChildContentPage>>; CHILD_CONTENT_PAGES],
        len: usize,
    }

    impl Default for ChildContentRoot {
        fn default() -> Self {
            Self { pages: std::array::from_fn(|_| None), len: 0 }
        }
    }

    #[derive(Clone, Default)]
    pub struct ChildContentView {
        pub(crate) root: Option<std::sync::Arc<ChildContentRoot>>,
    }

    impl ChildContentView {
        /// 🈳️ The view a document with no children gets.
        pub const EMPTY: Self = Self { root: None };

        fn hash(slot: &str, child_id: &str) -> Result<usize, Fault> {
            if slot.len() > CHILD_CONTENT_ID_BYTES || child_id.len() > CHILD_CONTENT_ID_BYTES {
                return Err(plugin_sdk_fault("child slot or id exceeds the fixed immutable-root identity bound"));
            }
            let mut hash = 0xcbf29ce484222325u64;
            for byte in slot.bytes().chain(std::iter::once(0xff)).chain(child_id.bytes()) {
                hash ^= u64::from(byte);
                hash = hash.wrapping_mul(0x100000001b3);
            }
            Ok(hash as usize % CHILD_CONTENT_SLOTS)
        }

        fn entry_at(root: &ChildContentRoot, index: usize) -> Option<&std::sync::Arc<ChildContentEntry>> {
            root.pages[index / CHILD_CONTENT_PAGE_SLOTS].as_ref()?.entries[index % CHILD_CONTENT_PAGE_SLOTS].as_ref()
        }

        fn locate(root: &ChildContentRoot, slot: &str, child_id: &str) -> Result<Result<usize, usize>, Fault> {
            let start = Self::hash(slot, child_id)?;
            for offset in 0..CHILD_CONTENT_SLOTS {
                let index = (start + offset) % CHILD_CONTENT_SLOTS;
                match Self::entry_at(root, index) {
                    Some(entry) if entry.slot == slot && entry.child_id == child_id => return Ok(Ok(index)),
                    Some(_) => {}
                    None => return Ok(Err(index)),
                }
            }
            Err(plugin_sdk_fault("fixed immutable child-content root is saturated"))
        }

        fn admit_member(&self, slot: &str, child_id: &str) -> Result<usize, Fault> {
            match self.root.as_deref() {
                Some(root) => Self::locate(root, slot, child_id).map(|location| match location {
                    Ok(index) | Err(index) => index,
                }),
                None => Self::hash(slot, child_id),
            }
        }

        fn insert_entry_admitted(&self, index: usize, entry: ChildContentEntry) -> Self {
            let root = self.root.as_deref().cloned().unwrap_or_default();
            let page_index = index / CHILD_CONTENT_PAGE_SLOTS;
            let entry_index = index % CHILD_CONTENT_PAGE_SLOTS;
            let mut next = root;
            let mut page = next.pages[page_index].as_deref().cloned().unwrap_or_default();
            let added = page.entries[entry_index].is_none();
            page.entries[entry_index] = Some(std::sync::Arc::new(entry));
            next.pages[page_index] = Some(std::sync::Arc::new(page));
            next.len += usize::from(added);
            Self { root: Some(std::sync::Arc::new(next)) }
        }

        fn find(&self, slot: &str, child_id: &str) -> Result<Option<&ChildContentEntry>, Fault> {
            let Some(root) = self.root.as_deref() else { return Ok(None) };
            match Self::locate(root, slot, child_id)? {
                Ok(index) => Ok(Self::entry_at(root, index).map(std::sync::Arc::as_ref)),
                Err(_) => Ok(None),
            }
        }

        /// 🪪 Stable identity of the immutable child-resolution root retained by one job request.
        pub fn identity_digest(&self) -> u64 {
            let Some(root) = self.root.as_deref() else { return 0xcbf2_9ce4_8422_2325 };
            let mut digest = 0xcbf2_9ce4_8422_2325_u64;
            for entry in root.pages.iter().flatten().flat_map(|page| page.entries.iter().flatten()) {
                for byte in entry
                    .slot
                    .bytes()
                    .chain(std::iter::once(0xff))
                    .chain(entry.child_id.bytes())
                    .chain(std::iter::once(0xfe))
                    .chain(entry.dialect.artifact_kind.bytes())
                    .chain(std::iter::once(0xfd))
                    .chain(entry.dialect.standard.bytes())
                    .chain(std::iter::once(0xfc))
                    .chain(entry.dialect.subset.bytes())
                    .chain(entry.revision)
                {
                    digest = (digest ^ u64::from(byte)).wrapping_mul(0x1000_0000_01b3);
                }
            }
            digest
        }

        fn contains_entry_owner(&self, entry: &std::sync::Arc<ChildContentEntry>) -> bool {
            self.find(&entry.slot, &entry.child_id).ok().flatten().is_some_and(|candidate| std::ptr::eq(candidate, entry.as_ref()))
        }

        fn take_one(&mut self, current: &ChildContentView) -> ChildContentTake {
            let Some(root) = self.root.take() else { return ChildContentTake::Complete };
            let mut root = match std::sync::Arc::try_unwrap(root) {
                Ok(root) => root,
                Err(shared) => {
                    self.root = Some(shared);
                    return ChildContentTake::Blocked;
                }
            };
            for page_index in 0..CHILD_CONTENT_PAGES {
                let Some(page) = root.pages[page_index].take() else { continue };
                let mut page = match std::sync::Arc::try_unwrap(page) {
                    Ok(page) => page,
                    Err(shared) => {
                        let retained_by_current = current.root.as_deref().and_then(|current| current.pages[page_index].as_ref()).is_some_and(|candidate| std::sync::Arc::ptr_eq(candidate, &shared));
                        if !retained_by_current {
                            root.pages[page_index] = Some(shared);
                            self.root = Some(std::sync::Arc::new(root));
                            return ChildContentTake::Blocked;
                        }
                        let shared_entries = shared.entries.iter().flatten().count();
                        drop(shared);
                        root.len = root.len.saturating_sub(shared_entries);
                        self.root = (root.len != 0).then(|| std::sync::Arc::new(root));
                        return ChildContentTake::ReleasedShared;
                    }
                };
                for entry_index in 0..CHILD_CONTENT_PAGE_SLOTS {
                    let Some(entry) = page.entries[entry_index].take() else { continue };
                    return match std::sync::Arc::try_unwrap(entry) {
                        Ok(entry) => {
                            root.len = root.len.saturating_sub(1);
                            if page.entries.iter().any(Option::is_some) {
                                root.pages[page_index] = Some(std::sync::Arc::new(page));
                            }
                            self.root = (root.len != 0).then(|| std::sync::Arc::new(root));
                            ChildContentTake::Snapshot(entry)
                        }
                        Err(shared) => {
                            if current.contains_entry_owner(&shared) {
                                drop(shared);
                                root.len = root.len.saturating_sub(1);
                                if page.entries.iter().any(Option::is_some) {
                                    root.pages[page_index] = Some(std::sync::Arc::new(page));
                                }
                                self.root = (root.len != 0).then(|| std::sync::Arc::new(root));
                                ChildContentTake::ReleasedShared
                            } else {
                                page.entries[entry_index] = Some(shared);
                                root.pages[page_index] = Some(std::sync::Arc::new(page));
                                self.root = Some(std::sync::Arc::new(root));
                                ChildContentTake::Blocked
                            }
                        }
                    };
                }
                self.root = (root.len != 0).then(|| std::sync::Arc::new(root));
                return ChildContentTake::ReleasedShared;
            }
            ChildContentTake::Complete
        }

        async fn with_member<M: SpaceMember>(&self, slot: &str, child_id: &str, dialect: &ArtifactDialect, member: &M) -> Result<Self, Fault> {
            let index = self.admit_member(slot, child_id)?;
            self.capture_member_admitted(index, slot, child_id, dialect, member).await
        }

        async fn capture_member_admitted<M: SpaceMember>(&self, index: usize, slot: &str, child_id: &str, dialect: &ArtifactDialect, member: &M) -> Result<Self, Fault> {
            let revision = member.content_revision().await;
            let snapshot = member.snapshot_read_erased().await.map_err(plugin_sdk_fault)?;
            Ok(self.insert_entry_admitted(index, ChildContentEntry { slot: slot.to_string(), child_id: child_id.to_string(), dialect: dialect.clone(), revision, snapshot }))
        }

        /// 🧬️ Fixed-size, restart-stable identity paired with the captured child snapshot.
        pub fn revision(&self, slot: &str, child_id: &str) -> Result<[u8; 32], Fault> {
            self.find(slot, child_id)?.map(|entry| entry.revision).ok_or_else(|| plugin_sdk_fault(format!("no live child store for slot {slot} child {child_id}")))
        }

        /// 🧵️ Selects an immutable child snapshot capability without exposing concrete ownership.
        pub fn typed_read<S: ArtifactPack + Send + Sync + 'static>(&self, slot: &str, child_id: &str) -> Result<store::SnapshotReadRef<'_, S>, Fault> {
            let snapshot = &self.find(slot, child_id)?.ok_or_else(|| plugin_sdk_fault(format!("no live child store for slot {slot} child {child_id}")))?.snapshot;
            snapshot.typed::<S>().ok_or_else(|| plugin_sdk_fault(format!("child snapshot type mismatch for slot {slot} child {child_id}")))
        }

        /// 🎯️ The dialect a child materializes as, for a caller that must route by kind.
        pub fn dialect(&self, slot: &str, child_id: &str) -> Option<ArtifactDialect> {
            self.find(slot, child_id).ok().flatten().map(|entry| entry.dialect.clone())
        }

        /// 📋️ Every `(slot, child_id)` currently live under this document.
        pub fn slots(&self) -> Vec<(String, String)> {
            let Some(root) = self.root.as_deref() else { return Vec::new() };
            let mut slots = Vec::with_capacity(root.len);
            for index in 0..CHILD_CONTENT_SLOTS {
                if let Some(entry) = Self::entry_at(root, index) {
                    slots.push((entry.slot.clone(), entry.child_id.clone()));
                }
            }
            slots
        }

        /// 🈳️ Whether this document has any live children at all.
        pub fn is_empty(&self) -> bool {
            self.root.as_ref().is_none_or(|root| root.len == 0)
        }
    }

    enum ChildContentTake {
        Blocked,
        ReleasedShared,
        Snapshot(ChildContentEntry),
        Complete,
    }

    pub(crate) struct ChildContentRetirement {
        view: std::mem::ManuallyDrop<ChildContentView>,
        pub(crate) pending: std::mem::ManuallyDrop<Option<ChildContentEntry>>,
        active: std::mem::ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,
        active_member: std::mem::ManuallyDrop<Option<(String, String)>>,
        require_member_terminal: bool,
    }

    impl ChildContentRetirement {
        fn new(view: ChildContentView, require_member_terminal: bool) -> Self {
            Self { view: std::mem::ManuallyDrop::new(view), pending: std::mem::ManuallyDrop::new(None), active: std::mem::ManuallyDrop::new(None), active_member: std::mem::ManuallyDrop::new(None), require_member_terminal }
        }

        fn close_step<M: SpaceMember>(&mut self, children: &mut ChildMemberRegistry<M>, current: &ChildContentView, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(active) = self.active.as_mut() {
                return match active.close_step(maximum_items, maximum_bytes).map_err(plugin_sdk_fault)? {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    store::SnapshotRetirementStep::Pending { .. } => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-snapshot-retirement-over-budget"), "child snapshot disposer exceeded its exact item or byte grant")),
                    store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "child snapshot disposer is waiting on external ownership" }),
                    store::SnapshotRetirementStep::Complete => {
                        if !active.terminal_is_empty() {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-snapshot-terminal-not-empty"), "child snapshot disposer reported Complete without its exact terminal-empty witness"));
                        }
                        drop(self.active.take());
                        if !self.require_member_terminal {
                            drop(self.active_member.take());
                        }
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                };
            }
            if let Some((slot, child_id)) = self.active_member.as_ref() {
                let Some(entry) = children.get_mut(&(slot.clone(), child_id.clone())) else {
                    return Ok(PluginCloseStep::Blocked { reason: "final child snapshot lease verification lost its exact live member owner" });
                };
                let member = &mut entry.member;
                if let Some(owner) = member.take_returned_snapshot_read_retirement().map_err(plugin_sdk_fault)? {
                    *self.active = Some(owner);
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                if !member.snapshot_read_leases_terminal_is_empty() {
                    return Ok(PluginCloseStep::Blocked { reason: "final child snapshot lease remains live outside the bounded return pump" });
                }
                drop(self.active_member.take());
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if self.pending.is_none() {
                match self.view.take_one(current) {
                    ChildContentTake::Blocked => return Ok(PluginCloseStep::Blocked { reason: "retired child root remains borrowed by an exact operation view" }),
                    ChildContentTake::ReleasedShared => return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                    ChildContentTake::Snapshot(entry) => *self.pending = Some(entry),
                    ChildContentTake::Complete => {
                        let empty = std::mem::replace(&mut *self.view, ChildContentView::EMPTY);
                        drop(empty);
                        return Ok(PluginCloseStep::Complete);
                    }
                }
            }
            let entry = self.pending.take().expect("pending child snapshot authority exists");
            let Some(member_entry) = children.get_mut(&(entry.slot.clone(), entry.child_id.clone())) else {
                *self.pending = Some(entry);
                return Ok(PluginCloseStep::Blocked { reason: "retired child snapshot has no exact live member disposer owner" });
            };
            let member = &mut member_entry.member;
            let ChildContentEntry { slot, child_id, dialect, revision, snapshot } = entry;
            match member.retire_snapshot_read_erased(snapshot) {
                Ok(owner) => {
                    *self.active_member = Some((slot, child_id));
                    drop(dialect);
                    *self.active = Some(owner);
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                Err(rejected) => {
                    *self.pending = Some(ChildContentEntry { slot, child_id, dialect, revision, snapshot: rejected.snapshot });
                    Ok(PluginCloseStep::Blocked { reason: "child member has not installed its exact bounded snapshot retirement factory" })
                }
            }
        }

        fn terminal_is_empty(&self) -> bool {
            self.view.root.as_ref().is_none_or(|root| root.len == 0) && self.pending.is_none() && self.active.is_none() && self.active_member.is_none()
        }
    }

    impl Drop for ChildContentRetirement {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.terminal_is_empty(), "incomplete child-content retirement reached Drop without bounded disposal");
        }
    }

    struct SnapshotReadReturnPump {
        active: std::mem::ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,
    }

    impl SnapshotReadReturnPump {
        fn new() -> Self {
            Self { active: std::mem::ManuallyDrop::new(None) }
        }

        fn drive(&mut self, next: impl FnOnce() -> Result<Option<Box<dyn store::ErasedSnapshotRetirement>>, Fault>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(active) = self.active.as_mut() {
                return match active.close_step(maximum_items, maximum_bytes).map_err(plugin_sdk_fault)? {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    store::SnapshotRetirementStep::Pending { .. } => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.snapshot-read-return-over-budget"), "returned snapshot-read disposer exceeded its exact item or byte grant")),
                    store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "returned snapshot-read disposer is waiting on external ownership" }),
                    store::SnapshotRetirementStep::Complete => {
                        if !active.terminal_is_empty() {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.snapshot-read-return-terminal-not-empty"), "returned snapshot-read disposer reported Complete without its exact terminal-empty witness"));
                        }
                        drop(self.active.take());
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                };
            }
            match next()? {
                Some(owner) => {
                    *self.active = Some(owner);
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                None => Ok(PluginCloseStep::Complete),
            }
        }

        fn terminal_is_empty(&self) -> bool {
            self.active.is_none()
        }
    }

    impl Drop for SnapshotReadReturnPump {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.terminal_is_empty(), "returned snapshot-read pump reached Drop before its exact disposer was terminal-empty");
        }
    }

    #[cfg(test)]
    pub(super) struct ChildAdmissionTestState {
        pub(super) children_empty: bool,
        pub(super) generation: u64,
        pub(super) abort_generation: u64,
        pub(super) abort_empty: bool,
        pub(super) requested_abort_retained: bool,
        pub(super) content_empty: bool,
        pub(super) roots_retiring_empty: bool,
    }

    struct ChildMemberRetirement<M> {
        entry: std::mem::ManuallyDrop<Option<ChildMemberEntry<M>>>,
    }

    struct ChildStoreAdmission {
        key: (String, String),
        expected: ArtifactRef,
        owner: store::OwnerRef,
        member: ChildMemberAdmission,
        graph: store::OwnsAdmission,
        root_index: usize,
        generation: u64,
    }

    impl<M: SpaceMember> ChildMemberRetirement<M> {
        fn new(entry: ChildMemberEntry<M>) -> Self {
            Self { entry: std::mem::ManuallyDrop::new(Some(entry)) }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            let Some(entry) = self.entry.as_mut() else { return Ok(PluginCloseStep::Complete) };
            let member = &mut entry.member;
            match member.close_owned_step(maximum_items, maximum_bytes).map_err(plugin_sdk_fault)? {
                store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                store::SnapshotRetirementStep::Pending { .. } => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-close-over-budget"), "child member disposer exceeded its exact item or byte grant")),
                store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "child member is waiting for its required domain-owned bounded disposer" }),
                store::SnapshotRetirementStep::Complete => {
                    if !member.close_owned_terminal_is_empty() {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-member-close-terminal-not-empty"), "child member disposer reported Complete without its exact terminal-empty witness"));
                    }
                    let entry = self.entry.take().expect("terminal child member owner is present");
                    drop(entry);
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
            }
        }

        fn terminal_is_empty(&self) -> bool {
            self.entry.is_none()
        }
    }

    impl<M> Drop for ChildMemberRetirement<M> {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.entry.is_none(), "child-member retirement reached Drop before its exact owner was terminal-empty");
        }
    }

    /// @emoji 🧮️ Read-only view of an app's config snapshot — same role as {@link ArtifactView} for the
    /// config {@link ConfigStore} owned by {@link VcsArtifactApp}.
    pub struct ConfigView<'a, C> {
        pub snapshot: &'a C,
        pub window: Option<&'a WindowConfigSnapshot>,
    }

    impl<'a, C> ConfigView<'a, C> {
        pub fn window<O: WindowConfigOwner>(&self) -> Option<&O::State> {
            self.window.and_then(WindowConfigSnapshot::get::<O>)
        }
    }

    /// @emoji 📝️ Read-only view of an app's volatile draft snapshot — same role as {@link ConfigView}
    /// for the draft {@link store::DraftStore} (ephemeral; never checkpoints).
    pub struct DraftView<'a, D> {
        pub snapshot: &'a D,
    }

    /// @emoji 👥️ Read-only view of the PRESENCE lane: this actor's own live shared state plus every
    /// peer's, as last broadcast. Ephemeral and shared — never persisted, never undoable.
    pub struct PresencePeersView<'a, P> {
        root: &'a store::PresencePeersRoot<P>,
    }

    impl<'a, P> PresencePeersView<'a, P> {
        /// 👥️ Iterates the already-sorted immutable peer root without projecting a roster.
        pub fn iter(&self) -> impl Iterator<Item = (&'a str, &'a P)> {
            self.root.peers()
        }

        pub fn len(&self) -> usize {
            self.root.len()
        }

        pub fn is_empty(&self) -> bool {
            self.root.is_empty()
        }
    }

    pub struct PresenceView<'a, P> {
        /// 👤️ This actor's own presence — the value that gets broadcast.
        pub local: &'a P,
        /// 👥️ Every other peer's presence, sorted by actor id for a stable render order.
        pub peers: PresencePeersView<'a, P>,
    }

    /// @emoji 🫧️ Read-only view of the TRANSIENT lane: ephemeral state local to this client that is
    /// never document content — the typed replacement for plugin `thread_local!` scratch state.
    pub struct TransientView<'a, T> {
        pub snapshot: &'a T,
        pub window: Option<&'a WindowTransientSnapshot>,
    }

    impl<T> TransientView<'_, T> {
        pub fn window<O: WindowTransientOwner>(&self) -> Option<&O::State> {
            self.window.and_then(WindowTransientSnapshot::get::<O>)
        }
    }

    //#region 🔖️InteractionView
    /// @emoji 👥️ One OTHER peer's last-adopted artifact/app-scope presence slice — the plugin-side
    /// twin of `PresencePeer`'s `color`/`surface`/`interaction` fields, keyed by actor in
    /// `VcsArtifactApp::peer_presence` (contract-freeze §C7.6). `presence_pack`'s decoded app-typed
    /// value is NOT carried here — it lands in `presence_store` instead (the existing peer-roster
    /// mechanism, unchanged), so this struct stays generic over every `ArtifactApp`.
    #[derive(Clone, Debug, Default, PartialEq)]
    pub struct PeerPresence {
        pub color: Option<u8>,
        pub surface: Option<String>,
        pub interaction: Option<protocol::PresenceInteraction>,
    }

    const PEER_PRESENCE_SLOTS: usize = 64;
    const PEER_PRESENCE_ID_BYTES: usize = 256;

    struct PeerPresenceEntry {
        actor: String,
        presence: PeerPresence,
    }

    pub(crate) struct PeerPresenceRoot {
        entries: [Option<std::sync::Arc<PeerPresenceEntry>>; PEER_PRESENCE_SLOTS],
        len: usize,
    }

    impl PeerPresenceRoot {
        pub(crate) fn empty() -> Self {
            Self { entries: std::array::from_fn(|_| None), len: 0 }
        }

        fn empty_shared() -> std::sync::Arc<Self> {
            static EMPTY: std::sync::OnceLock<std::sync::Arc<PeerPresenceRoot>> = std::sync::OnceLock::new();
            EMPTY.get_or_init(|| std::sync::Arc::new(Self::empty())).clone()
        }

        pub(crate) fn insert(&mut self, actor: String, presence: PeerPresence) -> Result<(), Fault> {
            if actor.is_empty() || actor.len() > PEER_PRESENCE_ID_BYTES {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-presence-actor"), "peer actor identity is empty or exceeds its fixed byte authority"));
            }
            let mut index = 0usize;
            while index < self.len && self.entries[index].as_ref().is_some_and(|entry| entry.actor.as_str() < actor.as_str()) {
                index += 1;
            }
            if self.entries.get(index).and_then(Option::as_ref).is_some_and(|entry| entry.actor == actor) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-presence-duplicate"), "one presence roster contains a duplicate actor identity"));
            }
            if self.len == PEER_PRESENCE_SLOTS {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-presence-capacity"), "presence roster exceeds its fixed peer authority"));
            }
            for cursor in (index..self.len).rev() {
                self.entries[cursor + 1] = self.entries[cursor].take();
            }
            self.entries[index] = Some(std::sync::Arc::new(PeerPresenceEntry { actor, presence }));
            self.len += 1;
            Ok(())
        }

        fn iter(&self) -> impl Iterator<Item = (&str, &PeerPresence)> {
            self.entries[..self.len].iter().filter_map(|entry| entry.as_deref().map(|entry| (entry.actor.as_str(), &entry.presence)))
        }

        pub(crate) fn get(&self, actor: &str) -> Option<&PeerPresence> {
            self.iter().find_map(|(candidate, presence)| (candidate == actor).then_some(presence))
        }

        pub(crate) fn contains_key(&self, actor: &str) -> bool {
            self.get(actor).is_some()
        }

        #[cfg(test)]
        pub(crate) fn len(&self) -> usize {
            self.len
        }

        pub(crate) fn is_empty(&self) -> bool {
            self.len == 0
        }
    }

    struct PeerPresenceEntryRetirement {
        entry: std::mem::ManuallyDrop<Option<PeerPresenceEntry>>,
        domain: std::mem::ManuallyDrop<Option<protocol::PresenceDomain>>,
    }

    impl PeerPresenceEntryRetirement {
        fn new(entry: PeerPresenceEntry) -> Self {
            Self { entry: std::mem::ManuallyDrop::new(Some(entry)), domain: std::mem::ManuallyDrop::new(None) }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if let Some(domain) = self.domain.as_mut() {
                if let Some(value) = domain.selected.pop() {
                    if value.len() > maximum_bytes {
                        domain.selected.push(value);
                        return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                    }
                    let bytes = value.len();
                    drop(value);
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: bytes };
                }
                if let Some(value) = domain.hovered.pop() {
                    if value.len() > maximum_bytes {
                        domain.hovered.push(value);
                        return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                    }
                    let bytes = value.len();
                    drop(value);
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: bytes };
                }
                let domain = self.domain.take().expect("active peer-presence domain authority");
                let bytes = domain.domain.len().saturating_add(domain.granularity.len());
                if bytes > maximum_bytes {
                    *self.domain = Some(domain);
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(domain);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: bytes };
            }
            let Some(entry) = self.entry.as_mut() else { return PluginCloseStep::Complete };
            if let Some(interaction) = entry.presence.interaction.as_mut() {
                if let Some(domain) = interaction.domains.pop() {
                    *self.domain = Some(domain);
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
                if interaction.app_id.len() > maximum_bytes {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                let interaction = entry.presence.interaction.take().expect("empty peer interaction authority");
                let bytes = interaction.app_id.len();
                drop(interaction);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: bytes };
            }
            if let Some(surface) = entry.presence.surface.take() {
                if surface.len() > maximum_bytes {
                    entry.presence.surface = Some(surface);
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                let bytes = surface.len();
                drop(surface);
                return PluginCloseStep::Pending { released_items: 1, released_bytes: bytes };
            }
            if entry.actor.len() > maximum_bytes {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            let bytes = entry.actor.len();
            entry.actor.clear();
            let entry = self.entry.take().expect("peer-presence entry authority");
            drop(entry);
            PluginCloseStep::Pending { released_items: 1, released_bytes: bytes }
        }

        fn terminal_is_empty(&self) -> bool {
            self.entry.is_none() && self.domain.is_none()
        }
    }

    impl Drop for PeerPresenceEntryRetirement {
        fn drop(&mut self) {
            debug_assert!(std::thread::panicking() || self.terminal_is_empty(), "incomplete peer-presence entry reached Drop without bounded disposal");
        }
    }

    pub(crate) struct PeerPresenceRootRetirement {
        root: std::mem::ManuallyDrop<Option<std::sync::Arc<PeerPresenceRoot>>>,
        owned: std::mem::ManuallyDrop<Option<PeerPresenceRoot>>,
        entry: std::mem::ManuallyDrop<Option<PeerPresenceEntryRetirement>>,
        cursor: usize,
    }

    impl PeerPresenceRootRetirement {
        fn new(root: std::sync::Arc<PeerPresenceRoot>) -> Self {
            Self { root: std::mem::ManuallyDrop::new(Some(root)), owned: std::mem::ManuallyDrop::new(None), entry: std::mem::ManuallyDrop::new(None), cursor: 0 }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(entry) = self.entry.as_mut() {
                let step = entry.close_step(maximum_items, maximum_bytes);
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                if !entry.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-presence-entry-terminal-not-empty"), "peer-presence entry reported Complete without an empty terminal witness"));
                }
                drop(self.entry.take());
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if self.owned.is_none() {
                let root = self.root.take().expect("peer-presence root retirement authority");
                match std::sync::Arc::try_unwrap(root) {
                    Ok(root) => *self.owned = Some(root),
                    Err(root) => {
                        *self.root = Some(root);
                        return Ok(PluginCloseStep::Blocked { reason: "peer-presence root remains captured by a live operation" });
                    }
                }
            }
            let root = self.owned.as_mut().expect("unique peer-presence retirement root");
            while self.cursor < root.len {
                let index = self.cursor;
                self.cursor += 1;
                let Some(entry) = root.entries[index].take() else { continue };
                let entry = std::sync::Arc::try_unwrap(entry).map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-presence-entry-shared"), "a unique retired peer root retained a foreign entry owner"))?;
                *self.entry = Some(PeerPresenceEntryRetirement::new(entry));
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            root.len = 0;
            let root = self.owned.take().expect("empty peer-presence root shell");
            drop(root);
            Ok(PluginCloseStep::Complete)
        }

        fn terminal_is_empty(&self) -> bool {
            self.root.is_none() && self.owned.is_none() && self.entry.is_none()
        }
    }

    impl Drop for PeerPresenceRootRetirement {
        fn drop(&mut self) {
            debug_assert!(std::thread::panicking() || self.terminal_is_empty(), "incomplete peer-presence root reached Drop without bounded disposal");
        }
    }

    pub(crate) const PEER_ROSTER_WIRE_BYTES: usize = 4_096;

    pub struct PresenceRosterAdmission {
        seq: u64,
        generation: u64,
        pub(crate) cancel: semio_framework_job::CancelToken,
    }

    impl PresenceRosterAdmission {
        pub(crate) fn sequence(&self) -> u64 {
            self.seq
        }

        pub fn generation(&self) -> u64 {
            self.generation
        }
    }

    pub struct PresenceRosterOutcome {
        pub seq: u64,
        pub fault: Option<Fault>,
    }

    struct PeerRosterCandidate<P> {
        seq: u64,
        generation: u64,
        cancel: semio_framework_job::CancelToken,
        own_color: Option<u8>,
        now_ms: i64,
        root: std::sync::Arc<PeerPresenceRoot>,
        typed: store::PresencePeersCommit<P>,
    }

    struct ValidatedPeerRosterCommit {
        generation: u64,
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum PeerRosterPublicationStage {
        DecodeMetadata,
        PruneTyped,
        DecodeTyped,
        ReleaseCreated,
        Ready,
    }

    /// 📦️ Fixed slots retaining each peer identity and its encoded presence.
    type PeerPresencePacks = [Option<(String, Vec<u8>)>; PEER_PRESENCE_SLOTS];

    pub(crate) struct PeerRosterPublication<A: ArtifactApp> {
        seq: u64,
        generation: u64,
        own_color: Option<u8>,
        now_ms: i64,
        cancel: semio_framework_job::CancelToken,
        raw: protocol::PresenceCommandCursor,
        candidate: std::mem::ManuallyDrop<Option<PeerPresenceRoot>>,
        retirement: std::mem::ManuallyDrop<Option<PeerPresenceRootRetirement>>,
        packs: std::mem::ManuallyDrop<PeerPresencePacks>,
        packs_len: usize,
        packs_shell_released: bool,
        typed: std::mem::ManuallyDrop<Option<store::PresencePeersPublication<A::Presence>>>,
        rejected: std::mem::ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,
        stage: PeerRosterPublicationStage,
        faulted: bool,
        fault: Option<Fault>,
    }

    impl<A: ArtifactApp> PeerRosterPublication<A> {
        fn new(admission: PresenceRosterAdmission, now_ms: i64, raw: protocol::PresenceCommandCursor) -> Self {
            Self {
                seq: admission.seq,
                generation: admission.generation,
                own_color: raw.own_color(),
                now_ms,
                cancel: admission.cancel,
                raw,
                candidate: std::mem::ManuallyDrop::new(Some(PeerPresenceRoot::empty())),
                retirement: std::mem::ManuallyDrop::new(None),
                packs: std::mem::ManuallyDrop::new(std::array::from_fn(|_| None)),
                packs_len: 0,
                packs_shell_released: false,
                typed: std::mem::ManuallyDrop::new(None),
                rejected: std::mem::ManuallyDrop::new(None),
                stage: PeerRosterPublicationStage::DecodeMetadata,
                faulted: false,
                fault: None,
            }
        }

        fn fail(&mut self, fault: Fault) -> PluginCloseStep {
            self.faulted = true;
            if self.fault.is_none() {
                self.fault = Some(fault);
            }
            PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }
        }

        fn rejected(admission: PresenceRosterAdmission, raw: FixedCommandPage, fault: Fault) -> Self {
            let seq = admission.seq;
            let mut publication = Self::new(admission, 0, protocol::PresenceCommandCursor::retain_rejected(raw, seq));
            publication.fail(fault);
            publication
        }

        #[expect(clippy::result_large_err, reason = "Refusal returns the original fixed-capacity input so its caller can retry or retire that exact owner without an extra allocation.")]
        fn push_page(&mut self, page_index: u32, page: FixedCommandPage) -> Result<(), (Fault, FixedCommandPage)> {
            self.raw.push_page(page_index, page).map_err(|(error, page)| (error.into_fault(), page))
        }

        fn release_packs_shell(&mut self) {
            if !self.packs_shell_released {
                debug_assert_eq!(self.packs_len, 0);
                // SAFETY: every owned pack was transferred or released in a bounded step and this
                // exact flag makes the fixed empty shell release once.
                unsafe { std::mem::ManuallyDrop::drop(&mut self.packs) };
                self.packs_shell_released = true;
            }
        }

        fn step(&mut self, presence_store: &store::PresenceStore<A::Presence, A::PresenceMutation>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if resolve_ready(self.cancel.is_cancelled()) {
                return Ok(self.fail(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-cancelled"), "peer roster publication was cancelled before commit")));
            }
            match self.stage {
                PeerRosterPublicationStage::DecodeMetadata => {
                    if self.raw.terminal_is_empty() {
                        *self.typed = Some(presence_store.begin_peer_publication().map_err(plugin_sdk_fault)?);
                        self.stage = PeerRosterPublicationStage::PruneTyped;
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                    if self.raw.waiting_for_page() {
                        return Ok(PluginCloseStep::Blocked { reason: "peer roster publication is waiting for its next exact page owner" });
                    }
                    let next_len = match self.raw.next_len() {
                        Ok(next_len) => next_len,
                        Err(error) => return Ok(self.fail(plugin_sdk_fault(error.to_string()))),
                    };
                    let Some(next_len) = next_len else {
                        let (complete, released_bytes) = self.raw.close_release(maximum_bytes);
                        return Ok(PluginCloseStep::Pending { released_items: usize::from(complete), released_bytes });
                    };
                    if next_len > maximum_bytes {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    let raw = match self.raw.take_next() {
                        Ok(Some(raw)) => raw,
                        Ok(None) => unreachable!("presence cursor advertised one retained entry"),
                        Err(error) => return Ok(self.fail(plugin_sdk_fault(error.to_string()))),
                    };
                    let bytes = raw.len();
                    let decoded = resolve_ready(protocol::decode_presence_peer(raw.as_slice()));
                    match decoded {
                        Ok(peer) => {
                            let protocol::PresencePeer { actor, presence_pack, color, surface, interaction, .. } = peer;
                            let pack_actor = presence_pack.as_ref().map(|_| actor.clone());
                            if let Err(fault) = self
                                .candidate
                                .as_mut()
                                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-candidate"), "peer roster candidate was already transferred"))?
                                .insert(actor, PeerPresence { color, surface, interaction })
                            {
                                return Ok(self.fail(fault));
                            }
                            if let (Some(actor), Some(pack)) = (pack_actor, presence_pack) {
                                if pack.len() > PEER_ROSTER_WIRE_BYTES || self.packs_len == PEER_PRESENCE_SLOTS {
                                    return Ok(self.fail(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-presence-pack-cap"), "one app-typed presence pack exceeds its fixed decode authority")));
                                }
                                self.packs[self.packs_len] = Some((actor, pack));
                                self.packs_len += 1;
                            }
                        }
                        Err(error) => return Ok(self.fail(plugin_sdk_fault(error.to_string()))),
                    }
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes })
                }
                PeerRosterPublicationStage::PruneTyped => {
                    let root = self.candidate.as_ref().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-candidate"), "peer roster metadata candidate was already transferred"))?;
                    let progressed = self
                        .typed
                        .as_mut()
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-candidate"), "app-typed peer candidate was not initialized"))?
                        .prune_one(|actor| root.contains_key(actor))
                        .map_err(plugin_sdk_fault)?;
                    if !progressed {
                        self.stage = PeerRosterPublicationStage::DecodeTyped;
                    }
                    Ok(PluginCloseStep::Pending { released_items: usize::from(progressed), released_bytes: 0 })
                }
                PeerRosterPublicationStage::DecodeTyped => {
                    if self.packs_len == 0 {
                        self.release_packs_shell();
                        self.stage = PeerRosterPublicationStage::ReleaseCreated;
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                    let (_actor, pack) = self.packs[self.packs_len - 1].as_ref().expect("retained app-typed presence pack");
                    if pack.len() > maximum_bytes {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    let (actor, pack) = self.packs[self.packs_len - 1].take().expect("retained app-typed presence pack");
                    self.packs_len -= 1;
                    let bytes = pack.len();
                    let presence = match A::Presence::decode_pack(&pack) {
                        Ok(presence) => presence,
                        Err(error) => {
                            return Ok(self.fail(plugin_sdk_fault(error.to_string())));
                        }
                    };
                    drop(pack);
                    let typed = self.typed.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-candidate"), "app-typed peer candidate was already transferred"))?;
                    if let Err(rejected) = typed.adopt(actor, presence, self.now_ms) {
                        let reason = rejected.reason;
                        *self.rejected = Some(rejected.into_retirement());
                        return Ok(self.fail(plugin_sdk_fault(reason)));
                    }
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes })
                }
                PeerRosterPublicationStage::ReleaseCreated => {
                    let released = self.typed.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-candidate"), "app-typed peer candidate was already transferred"))?.release_created_one();
                    if !released {
                        self.stage = PeerRosterPublicationStage::Ready;
                    }
                    Ok(PluginCloseStep::Pending { released_items: usize::from(released), released_bytes: 0 })
                }
                PeerRosterPublicationStage::Ready => Ok(PluginCloseStep::Complete),
            }
        }

        fn take_candidate(&mut self) -> Result<PeerRosterCandidate<A::Presence>, Fault> {
            if self.faulted || self.stage != PeerRosterPublicationStage::Ready || !self.raw.terminal_is_empty() || !self.packs_shell_released {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-not-ready"), "peer roster candidate was requested before every retained stage completed"));
            }
            let metadata = self.candidate.take().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-candidate"), "peer roster metadata candidate was already transferred"))?;
            let typed = match self.typed.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-candidate"), "app-typed peer candidate was already transferred"))?.take_commit() {
                Ok(typed) => typed,
                Err(error) => {
                    *self.candidate = Some(metadata);
                    return Err(plugin_sdk_fault(error));
                }
            };
            let typed_shell = self.typed.take().expect("terminal app-typed peer candidate");
            assert!(typed_shell.terminal_is_empty(), "take_commit consumes every app-typed publication owner before its shell is released");
            drop(typed_shell);
            let root = std::sync::Arc::new(metadata);
            Ok(PeerRosterCandidate { seq: self.seq, generation: self.generation, cancel: self.cancel.clone(), own_color: self.own_color, now_ms: self.now_ms, root, typed })
        }

        fn retain_rejected_candidate(&mut self, candidate: PeerRosterCandidate<A::Presence>) {
            assert!(self.terminal_is_empty(), "returned peer candidate must rejoin its exact empty publication owner");
            *self.retirement = Some(PeerPresenceRootRetirement::new(candidate.root));
            *self.rejected = Some(Box::new(candidate.typed.into_retirement()));
            self.fail(plugin_sdk_fault("presence peer publication lost its exact live base or factory authority"));
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(retirement) = self.retirement.as_mut() {
                let step = retirement.close_step(maximum_items, maximum_bytes)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                if !retirement.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-terminal-not-empty"), "peer roster candidate retirement reported Complete without an empty terminal witness"));
                }
                drop(self.retirement.take());
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(rejected) = self.rejected.as_mut() {
                return match rejected.close_step(maximum_items, maximum_bytes).map_err(plugin_sdk_fault)? {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    store::SnapshotRetirementStep::Pending { .. } => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-rejected-over-budget"), "rejected app-typed presence disposer exceeded its exact grant")),
                    store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "rejected app-typed presence remains externally owned" }),
                    store::SnapshotRetirementStep::Complete => {
                        if !rejected.terminal_is_empty() {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-rejected-terminal-not-empty"), "rejected app-typed presence disposer reported Complete without an empty terminal witness"));
                        }
                        drop(self.rejected.take());
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                };
            }
            if !self.raw.terminal_is_empty() {
                let (complete, released_bytes) = self.raw.close_release(maximum_bytes);
                return Ok(PluginCloseStep::Pending { released_items: usize::from(complete), released_bytes });
            }
            if self.packs_len != 0 {
                let (_, pack) = self.packs[self.packs_len - 1].as_ref().expect("retained app-typed presence close pack");
                if pack.len() > maximum_bytes {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                let (_, pack) = self.packs[self.packs_len - 1].take().expect("retained app-typed presence close pack");
                self.packs_len -= 1;
                let bytes = pack.len();
                drop(pack);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes });
            }
            self.release_packs_shell();
            if let Some(root) = self.candidate.take() {
                *self.retirement = Some(PeerPresenceRootRetirement::new(std::sync::Arc::new(root)));
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(typed) = self.typed.as_mut() {
                let step = typed.close_step(maximum_items, maximum_bytes).map_err(plugin_sdk_fault)?;
                if step != store::SnapshotRetirementStep::Complete {
                    return Ok(match step {
                        store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => PluginCloseStep::Pending { released_items, released_bytes },
                        store::SnapshotRetirementStep::Pending { .. } => {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-over-budget"), "app-typed peer candidate cleanup exceeded its exact grant"));
                        }
                        store::SnapshotRetirementStep::Blocked => PluginCloseStep::Blocked { reason: "app-typed peer candidate cleanup remains externally blocked" },
                        store::SnapshotRetirementStep::Complete => unreachable!(),
                    });
                }
                if !typed.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-terminal-not-empty"), "app-typed peer candidate cleanup reported Complete without its exact terminal witness"));
                }
                drop(self.typed.take());
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(PluginCloseStep::Complete)
        }

        fn terminal_is_empty(&self) -> bool {
            self.raw.terminal_is_empty() && self.packs_shell_released && self.candidate.is_none() && self.retirement.is_none() && self.typed.is_none() && self.rejected.is_none()
        }
    }

    impl<A: ArtifactApp> Drop for PeerRosterPublication<A> {
        fn drop(&mut self) {
            debug_assert!(std::thread::panicking() || self.terminal_is_empty(), "incomplete peer roster publication reached Drop without bounded disposal");
        }
    }

    /// @emoji 👥️ One peer's mark on a single interaction target — `InteractionView::peers_selecting`/
    /// `peers_hovering`'s element type (contract-freeze §C7.6), sorted by actor.
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct PeerMark<'a> {
        pub actor: &'a str,
        pub color: Option<u8>,
    }

    /// 🈳️ Lazily-initialized empty fallbacks `InteractionView`'s accessors return for an undeclared or
    /// never-touched domain — one static pair shared across every instance, so the accessor methods
    /// below can return a plain `&DomainSelection`/`&DomainHover` (no `Option`, no per-call allocation)
    /// exactly like the ticket's specified signature.
    // 🚫️async: E1-adjacent pure lazily-initialized static accessor consumed by `unwrap_or_else`/
    // `match`'s sync arms in `InteractionView::selection`/`hover` — see R9.
    fn empty_domain_selection() -> &'static protocol::DomainSelection {
        static EMPTY: std::sync::OnceLock<protocol::DomainSelection> = std::sync::OnceLock::new();
        EMPTY.get_or_init(protocol::DomainSelection::default)
    }

    // 🚫️async: E1-adjacent pure lazily-initialized static accessor consumed by `unwrap_or_else`/
    // `match`'s sync arms in `InteractionView::selection`/`hover` — see R9.
    fn empty_domain_hover() -> &'static protocol::DomainHover {
        static EMPTY: std::sync::OnceLock<protocol::DomainHover> = std::sync::OnceLock::new();
        EMPTY.get_or_init(protocol::DomainHover::default)
    }

    /// 🕹️ Read-only view of the framework-owned INTERACTION mechanism (hover + selection + active
    /// mode/granularity per domain) — threaded into `ArtifactApp::handle`/`copy_fragment`/
    /// `cut_operations` so an app reads its own current selection/hover instead of ever storing it
    /// again itself. `state` is the persisted-local half (selection/mode/granularity, one
    /// `VcsArtifactApp::interaction_store` `ApplyInLane{lane: HistoryLane::Interaction}` dispatch away
    /// from every change); `hover` is the ephemeral-local half (`VcsArtifactApp::interaction_hover`,
    /// never persisted — see that field's own doc comment). Both are combined once per dispatch by
    /// `VcsArtifactApp::interaction_view`, never mutated through this read-only handle.
    pub struct InteractionView<'a> {
        pub(crate) state: &'a protocol::InteractionState,
        pub(crate) hover: &'a InteractionHoverState,
        /// @emoji 👥️ Every OTHER peer's last-adopted presence, keyed by actor — see
        /// `VcsArtifactApp::peer_presence`'s own doc comment. Sourced from `BTreeMap` iteration
        /// order, which is already sorted by actor.
        pub(crate) peers: &'a PeerPresenceRoot,
    }

    impl<'a> InteractionView<'a> {
        /// 🖱️ `domain`'s current selection — an empty `DomainSelection` (not `None`) for an undeclared
        /// or never-selected domain, so call sites never have to unwrap.
        pub fn selection(&self, domain: &str) -> &protocol::DomainSelection {
            self.state.selection.get(domain).unwrap_or_else(|| empty_domain_selection())
        }

        /// 🐁️ `domain`'s current hover on `channel` — empty when nothing is hovered on that channel
        /// right now. `InteractionState.hover` holds exactly one live channel per domain at a time (the
        /// most recently hovered — see `next_hover`'s doc), so a `channel` mismatch also reads empty
        /// rather than returning a stale different-channel hover.
        pub fn hover(&self, domain: &str, channel: &str) -> &protocol::DomainHover {
            match self.hover.get(domain) {
                Some(hover) if hover.channel == channel => hover,
                _ => empty_domain_hover(),
            }
        }

        /// 🪜️ `domain`'s active granularity id, `None` for an undeclared domain (never dispatched
        /// through `validate_state` yet — e.g. a registry-less test construction).
        pub fn active_granularity(&self, domain: &str) -> Option<&str> {
            self.state.active_granularity.get(domain).map(String::as_str)
        }

        /// 🔀️ `domain`'s active `SelectionMode`, `None` for an undeclared domain.
        pub fn active_mode(&self, domain: &str) -> Option<protocol::SelectionMode> {
            self.state.active_mode.get(domain).copied()
        }

        /// 👥️ Every OTHER peer currently selecting `id` within `domain`, sorted by actor
        /// (contract-freeze §C7.6) — `[]` for a peer with no adopted interaction, an interaction with
        /// no matching domain, or a domain where `id` is not in `selected`.
        // 🚫️async: E1 pure in-memory filter, no suspension point — see R9.
        //
        // ⚠️ Gap (SEMANTIC-UI-CONTRACT-AND-RENDERER-FAMILY packet `sdk-helpers` — see
        // `📓️terra-sdk-helpers-report.md`): the sync `marks_for` closure this used to feed
        // (`stamp_and_cache_interaction_ui`'s old presence-stamping half) is gone — that destination no
        // longer exists on a built node. This method itself is unaffected and still tested directly; a
        // future packet publishing real `PresenceUpdate`s is the next intended caller.
        pub fn peers_selecting(&self, domain: &str, id: &str) -> Vec<PeerMark<'a>> {
            self.peers
                .iter()
                .filter_map(|(actor, presence)| {
                    let interaction = presence.interaction.as_ref()?;
                    let matched = interaction.domains.iter().find(|candidate| candidate.domain == domain)?;
                    matched.selected.iter().any(|selected_id| selected_id == id).then_some(PeerMark { actor, color: presence.color })
                })
                .collect()
        }

        /// 👥️ `peers_selecting`'s hover twin — every OTHER peer currently hovering `id` within
        /// `domain`, sorted by actor.
        // 🚫️async: E1 pure in-memory filter — see `peers_selecting`'s doc for why this must be sync.
        pub fn peers_hovering(&self, domain: &str, id: &str) -> Vec<PeerMark<'a>> {
            self.peers
                .iter()
                .filter_map(|(actor, presence)| {
                    let interaction = presence.interaction.as_ref()?;
                    let matched = interaction.domains.iter().find(|candidate| candidate.domain == domain)?;
                    matched.hovered.iter().any(|hovered_id| hovered_id == id).then_some(PeerMark { actor, color: presence.color })
                })
                .collect()
        }
    }
    //#endregion 🔖️InteractionView

