    /// 🧩️ Typed state owned by each embedding plugin's `plugin_exports!` expansion.
    pub struct PluginRuntime<PA: PluginApp> {
        pub(crate) guest_lifetimes: RefCell<crate::reactor::instance_lifetime::NativeLifecycleRegistry<PA>>,
        plugin: RefCell<Option<Plugin<PA>>>,
        plugin_assembly_error: RefCell<Option<Fault>>,
        instances: RefCell<RuntimeInstanceRegistry<std::sync::Arc<RuntimeAppCell<PA>>>>,
        close_quarantine: RefCell<RuntimeInstanceRegistry<RuntimeCloseEntry<PA>>>,
        close_cleanup_cursor: Cell<usize>,
        live_cleanup_cursor: Cell<usize>,
        typed_continuation_cursor: Cell<usize>,
        close_generation: Cell<u64>,
        local_interaction_query_generation: crate::local_interaction::live::LocalInteractionQueryGeneration,
        instance_actors: RefCell<RuntimeInstanceRegistry<RuntimeActorAuthority>>,
        document_backbones: RefCell<RuntimeInstanceRegistry<RuntimeDocumentBackboneBindingV1>>,
    }

    impl<PA: PluginApp> Default for PluginRuntime<PA> {
        fn default() -> Self {
            Self::new()
        }
    }

    impl<PA: PluginApp> PluginRuntime<PA> {
        /// 🧩️ Creates an empty typed runtime without erasing the plugin-owned app enum.
        pub fn new() -> Self {
            Self {
                guest_lifetimes: RefCell::new(crate::reactor::instance_lifetime::NativeLifecycleRegistry::new()),
                plugin: RefCell::new(None),
                plugin_assembly_error: RefCell::new(None),
                instances: RefCell::new(RuntimeInstanceRegistry::new()),
                close_quarantine: RefCell::new(RuntimeInstanceRegistry::new()),
                close_cleanup_cursor: Cell::new(0),
                live_cleanup_cursor: Cell::new(0),
                typed_continuation_cursor: Cell::new(0),
                close_generation: Cell::new(0),
                local_interaction_query_generation: Default::default(),
                instance_actors: RefCell::new(RuntimeInstanceRegistry::new()),
                document_backbones: RefCell::new(RuntimeInstanceRegistry::new()),
            }
        }
    }

    /// 🌉️ Wire encode over `T: ToValue` directly — no `serde_json` detour. Ticket
    /// `26/09/01/RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS`: every caller's `T`
    /// (`Fault`, `Effect`, `DispatchReport`, …) now carries a first-party `ToValue` impl.
    fn encode_wire_serialized<T: ToValue>(value: &T) -> Vec<u8> {
        store::pack_rt::encode_wire_value(&value.to_value())
    }

    async fn push_app_fault(frames: &mut Vec<protocol::AppFrame>, in_reply_to: Option<u64>, fault: Fault) {
        frames.push(protocol::AppFrame::Error { in_reply_to, fault: encode_wire_serialized(&fault), report: Vec::new() });
    }

    async fn push_dispatch_fault(frames: &mut Vec<protocol::AppFrame>, in_reply_to: u64, fault: Fault, report: &protocol::DispatchReport) {
        frames.push(protocol::AppFrame::Error { in_reply_to: Some(in_reply_to), fault: encode_wire_serialized(&fault), report: encode_wire_serialized(report) });
    }

    async fn push_os_fault(frames: &mut Vec<protocol::AppFrame>, in_reply_to: Option<u64>, code: &str, message: String) {
        push_app_fault(frames, in_reply_to, Fault::new(FaultOrigin::Os, FaultCode::new(code), message)).await;
    }

    // 🚫️async: E1 pure error constructor consumed pervasively by sync closures
    // (`.map_err`/`.ok_or_else`) — see R9.
    fn plugin_internal_fault(message: impl Into<String>) -> Fault {
        Fault::new(FaultOrigin::Plugin, FaultCode::new("plugin.internal"), message)
    }

    pub(crate) fn debug_runtime_line(line: impl std::fmt::Display) {
        if semio_framework_trace::runtime_diagnostics_enabled() {
            eprintln!("{line}");
        }
    }

    #[cfg(test)]
    #[test]
    fn debug_runtime_lines_are_silent_when_diagnostics_are_off() {
        assert!(!semio_framework_trace::runtime_diagnostics_enabled());
    }

    /// 🌉️ Twin of `encode_wire_serialized` above — wire decode over `T: FromValue` directly.
    pub(crate) async fn decode_wire_serialized<T: FromValue>(bytes: &[u8]) -> Result<T, Fault> {
        let value = store::pack_rt::decode_wire_value(bytes).map_err(|error| plugin_internal_fault(error.to_string()))?;
        T::from_value(value).map_err(|error| plugin_internal_fault(error.to_string()))
    }

    async fn decode_wire_serialized_or<T: FromValue>(bytes: &[u8], default: T) -> T {
        decode_wire_serialized(bytes).await.unwrap_or(default)
    }

    /// ⚖️ Executes the channel's local policy command and returns its canonical acknowledgment frame.
    /// 🗃️ sdk-dedyn (O1/§1.5): generic `<PA: PluginApp>` replaces `&mut dyn PluginApp`.
    pub(crate) async fn set_merge_policy_frames<PA: PluginApp>(app: &mut PA, seq: u64, policy: u8) -> Result<Vec<protocol::AppFrame>, Fault> {
        let policy = protocol::MergePolicy::from_u8(policy).ok_or_else(|| Fault::new(FaultOrigin::Os, FaultCode::new("merge.invalid-policy"), format!("unknown merge policy ordinal {policy}")))?;
        app.set_merge_policy(policy).await;
        Ok(vec![protocol::AppFrame::Done { in_reply_to: seq }])
    }

    /// ⚔️ Executes the channel's conflict-resolution command and returns the authoritative report and open projection.
    pub(crate) async fn resolve_conflict_frames<PA: PluginApp>(app: &mut PA, seq: u64, conflict_id: String, resolution: u8) -> Result<Vec<protocol::AppFrame>, Fault> {
        let resolution = match resolution {
            0 => protocol::ConflictResolution::Accept,
            1 => protocol::ConflictResolution::Discard,
            _ => return Err(Fault::new(FaultOrigin::Os, FaultCode::new("merge.invalid-resolution"), format!("unknown conflict resolution ordinal {resolution}"))),
        };
        let report = app.resolve_conflict(&conflict_id, resolution).await?;
        let conflicts = app.open_conflicts().await;
        Ok(vec![protocol::AppFrame::MergeReport { in_reply_to: Some(seq), report: encode_wire_serialized(&report) }, protocol::AppFrame::Conflicts { in_reply_to: Some(seq), conflicts: encode_wire_serialized(&conflicts) }])
    }

    /// ⚔️ Executes the channel's open-conflict read command and returns its canonical projection frame.
    pub(crate) async fn read_conflicts_frames<PA: PluginApp>(app: &PA, seq: u64) -> Vec<protocol::AppFrame> {
        vec![protocol::AppFrame::Conflicts { in_reply_to: Some(seq), conflicts: encode_wire_serialized(&app.open_conflicts().await) }]
    }

    /// 🪪️ Reads the actor retained by exact instance-open admission, with a local fallback.
    pub(crate) async fn instance_actor<PA: PluginApp>(runtime: &PluginRuntime<PA>, instance_id: u32) -> String {
        runtime.instance_actors.try_borrow().ok().and_then(|actors| actors.get(instance_id).map(RuntimeActorAuthority::to_string)).unwrap_or_else(|| "local".to_string())
    }

    /// 🧬️ The local async mutex keeps the instance in-place across a suspending app call. Dropping an
    /// in-flight future releases the RAII guard and wakes the next caller without losing the instance.
    async fn with_instances_mut<PA: PluginApp, R, F: FnOnce(&mut RuntimeInstanceRegistry<std::sync::Arc<RuntimeAppCell<PA>>>) -> Result<R, Fault>>(runtime: &PluginRuntime<PA>, f: F) -> Result<R, Fault> {
        let mut instances = runtime.instances.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime instance authority is busy"))?;
        f(&mut instances)
    }

    /// 🧪️ MICROKERNEL-POOLED-ACTOR-PLUGIN-RUNTIME: registers `instance` directly into `INSTANCES`,
    /// bypassing `plugin_create_app_with_id`'s `PLUGIN`/`PluginProgram` requirement — a real
    /// `AsyncTask` resume test only needs A `dyn PluginApp` at a known id, not a fully assembled
    /// plugin bundle. `#[cfg(test)]`-gated, never part of the real API surface.
    #[cfg(test)]
    pub(crate) async fn test_push_instance<PA: PluginApp>(runtime: &PluginRuntime<PA>, instance: AppInstance<PA>) {
        with_instances_mut(runtime, |list| list.insert(instance.id, std::sync::Arc::new(RuntimeAppCell::new(instance))).map_err(|_| plugin_internal_fault("fixed runtime instance authority is saturated or collided")))
            .await
            .expect("test_push_instance must not fail");
    }

    static NEXT_INSTANCE_ID: AtomicU32 = AtomicU32::new(1);

    pub fn install_plugin_bundle<PA: PluginApp>(runtime: &PluginRuntime<PA>, bundle: Plugin<PA>) {
        *runtime.plugin.borrow_mut() = Some(bundle);
        *runtime.plugin_assembly_error.borrow_mut() = None;
    }

    /// 🧩️ Installs a successful plugin bundle or retains its typed assembly fault for WIT startup calls.
    pub fn install_plugin_bundle_result<PA: PluginApp>(runtime: &PluginRuntime<PA>, bundle: Result<Plugin<PA>, PluginAssemblyError>) {
        match bundle {
            Ok(bundle) => install_plugin_bundle(runtime, bundle),
            Err(error) => {
                *runtime.plugin_assembly_error.borrow_mut() = Some(Fault::new(FaultOrigin::Plugin, FaultCode::new(error.code), error.message));
            }
        }
    }

    static PLUGIN_INIT_ONCE: std::sync::Once = std::sync::Once::new();

    // 🚫️async: E4 fn-pointer slot
    static PLUGIN_BUNDLE_INSTALLER: std::sync::OnceLock<fn()> = std::sync::OnceLock::new();

    /// @emoji 🧩️ Registers the embedding plugin crate's bundle installer (expanded from `plugin_exports!`).
    pub fn register_plugin_bundle_installer(install: fn()) {
        let _ = PLUGIN_BUNDLE_INSTALLER.set(install);
    }

    /// 🔗️ Weak default so intermediate `cdylib` links (e.g. `semio-framework-os` pulled into a
    /// wasip2 plugin build via feature unification of `component-guest`) succeed; the embedding
    /// plugin's `plugin_exports!` provides the strong installer override.
    #[cfg(feature = "component-guest")]
    #[unsafe(no_mangle)]
    #[linkage = "weak"]
    pub extern "C" fn semio_plugin_bundle_installer_link_shim() {}

    /// Ensures the embedding plugin crate's bundle installer ran before any WIT export is served.
    // 🚫️async: E1 pure `std::sync::Once` init consumed by `component::wasip2`'s sync `world
    // actor` `Guest` impls (WIT-fixed, no `host-async` import exists to await in that world) — R9.
    // Body is entirely `call_once`'s sync closure (an `E4` fn-pointer install), zero suspension.
    pub fn ensure_plugin_initialized() {
        PLUGIN_INIT_ONCE.call_once(|| {
            // 🩹️ The owned hook uses only `std`, so every browser actor reports the exact Rust panic
            // through its WASI stderr stream before the target's normal abort trap terminates it.
            #[cfg(target_arch = "wasm32")]
            std::panic::set_hook(Box::new(|panic| eprintln!("[DEBUG] [semio-plugin panic] {panic}")));
            // 🧬️ A2 (design-abi.md §4): `host_port`/`HostBackboneChannel`/`set_host_backbone_channel`
            // are deleted per `important.md`'s "Replace, never wrap" list — a process-global backbone
            // channel cannot survive a pooled multi-instance actor. The per-instance `EffectBackbone`
            // that replaces it is NOT implemented in this wave (the VCS `BackboneChannelPort` trait's
            // `send`/`poll` methods are synchronous; bridging them onto the async `Effect`/`Event`
            // request-response model needs its own design decision — see the report's `lease-request`/
            // deferred-work section). No backbone channel is registered here; VCS backbone-dependent
            // paths surface a real "no host backbone linked" error instead of silently no-op'ing.
            #[cfg(feature = "component-guest")]
            {
                semio_plugin_bundle_installer_link_shim();
                if let Some(install) = PLUGIN_BUNDLE_INSTALLER.get() {
                    install();
                }
            }
        });
    }

    pub async fn plugin_manifest<PA: PluginApp>(runtime: &PluginRuntime<PA>) -> PluginManifest {
        ensure_plugin_initialized();
        if let Some(fault) = runtime.plugin_assembly_error.borrow().clone() {
            return PluginManifest {
                plugin_id: "assembly-failed".into(),
                label: fault.message,
                version: "0.0.0".into(),
                apps: vec![],
                examples: vec![],
                capabilities: vec![],
                topic_contributions: vec![],
                commands: vec![],
                artifact_kinds: vec![],
                dependencies: vec![],
                contributions: vec![],
            };
        }
        runtime.plugin.borrow().as_ref().map_or_else(
            || PluginManifest {
                plugin_id: "empty".into(),
                label: "Empty".into(),
                version: "0.0.0".into(),
                apps: vec![],
                examples: vec![],
                capabilities: vec![],
                topic_contributions: vec![],
                commands: vec![],
                artifact_kinds: vec![],
                dependencies: vec![],
                contributions: vec![],
            },
            Plugin::manifest,
        )
    }

    /// 🛂️ Builder-declared descriptor fields owned by the same Plugin as its manifest.
    #[derive(Clone, Default)]
    pub struct PluginDescriptorExtras {
        pub package_id: String,
        pub activation_events: Vec<ActivationEvent>,
        pub capability_requests: Vec<CapabilityRequest>,
        pub extension_points: Vec<ExtensionPointDeclaration>,
        pub execution: ExecutionMode,
        pub quotas: QuotaSchema,
        pub assets: Vec<AssetDeclaration>,
    }

    /// 📖️ Reads only the descriptor authority installed in this exact runtime.
    pub async fn plugin_descriptor_extras<PA: PluginApp>(runtime: &PluginRuntime<PA>) -> PluginDescriptorExtras {
        runtime.plugin.borrow().as_ref().map(|plugin| plugin.descriptor_extras().clone()).unwrap_or_default()
    }

    /// 🛂️ Re-encodes a packed `PackageDescriptor` with `hashes` blanked — shared by `plugin_exports!`/
    /// `extension_exports!`'s `descriptor_is_fresh()` tests. A NATIVE `describe_plugin()`/
    /// `describe_extension()` call always returns empty hashes (no wasm bytes exist yet to hash);
    /// the checked-in `🛂️.descriptor.semio` is the real `semio-framework-plugin-describe` emitter's
    /// output, with `wasm_sha256`/`core_wasm_sha256`/`descriptor_sha256` patched in after
    /// instantiating the built wasm. Comparing hashes between the two would make freshness
    /// permanently fail for every crate that ever commits a real descriptor — not drift, an
    /// unavoidable difference between "how" the two sides ran `describe()` — so both sides are
    /// hash-blanked before the byte comparison; hash correctness is `📇️registry:check`'s own gate
    /// (built wasm's SHA-256 vs `hashes.wasm_sha256`), not this test's job. `None` on any decode
    /// failure (caller treats that as "cannot compare", same as a missing file).
    /// 🌉️ Uses the descriptor's first-party structural codec so freshness observes exactly the
    /// same wire contract as guest `describe()` and never introduces a serde-shaped adapter.
    pub fn descriptor_bytes_with_blank_hashes(bytes: &[u8]) -> Option<Vec<u8>> {
        let value = store::pack_rt::decode_wire_value(bytes).ok()?;
        let mut descriptor: semio_framework::PackageDescriptor = from_dsl_value(value).ok()?;
        descriptor.hashes = semio_framework::PackageHashes { wasm_sha256: String::new(), core_wasm_sha256: String::new(), descriptor_sha256: String::new() };
        Some(store::pack_rt::encode_wire_value(&to_dsl_value(&descriptor).ok()?))
    }

    /// 💡️ Lists only inference services frozen into the installed plugin assembly.
    pub async fn plugin_wire_list_artifact_inference_services<PA: PluginApp>(runtime: &PluginRuntime<PA>) -> Result<Vec<u8>, crate::app::ArtifactInferenceExecutionError> {
        ensure_plugin_initialized();
        // 🌉️ `LocalKey::with`'s closure is sync — bridged via `resolve_ready` (no real suspension
        // point: the found-plugin branch resolves a frozen in-memory assembly).
        {
            let plugin = runtime.plugin.borrow();
            let plugin = plugin.as_ref().ok_or_else(|| crate::app::ArtifactInferenceExecutionError::new("artifact-inference.not-registered", "no plugin bundle is installed"))?;
            Ok(plugin.wire_list_artifact_inference_services())
        }
    }

    /// 💡️ Executes only an inference service frozen into the installed plugin assembly.
    pub async fn plugin_wire_artifact_infer<PA: PluginApp>(runtime: &PluginRuntime<PA>, request: &[u8]) -> Result<Vec<u8>, crate::app::ArtifactInferenceExecutionError> {
        ensure_plugin_initialized();
        // 🌉️ `LocalKey::with`'s closure is sync — bridged via `resolve_ready` (no real suspension
        // point: the found-plugin branch resolves a frozen in-memory assembly).
        {
            let plugin = runtime.plugin.borrow();
            let plugin = plugin.as_ref().ok_or_else(|| crate::app::ArtifactInferenceExecutionError::new("artifact-inference.not-registered", "no plugin bundle is installed"))?;
            plugin.wire_artifact_infer(request)
        }
    }

    /// 🎯️ Lists only mutation rows frozen into the installed plugin assembly.
    pub async fn plugin_wire_list_artifact_mutations<PA: PluginApp>(runtime: &PluginRuntime<PA>) -> Vec<u8> {
        ensure_plugin_initialized();
        // 🌉️ `LocalKey::with`'s closure is sync — bridged via `resolve_ready` for both the found-plugin
        // and no-plugin-yet branches (neither has a real suspension point).
        match runtime.plugin.borrow().as_ref() {
            Some(plugin) => Plugin::wire_list_artifact_mutations(plugin),
            None => encode_wire_serialized(&Vec::<crate::app::WireMutationRosterEntry>::new()),
        }
    }

    /// 🎯️ Plans only a mutation service frozen into the installed plugin assembly.
    pub async fn plugin_wire_artifact_mutation_plan<PA: PluginApp>(runtime: &PluginRuntime<PA>, request: &[u8]) -> Result<Vec<u8>, Fault> {
        ensure_plugin_initialized();
        // 🌉️ `LocalKey::with`'s closure is sync — bridged via `resolve_ready` (no real suspension
        // point: wire encode/decode plus a frozen in-memory mutation-plan lookup).
        runtime.plugin.borrow().as_ref().ok_or_else(|| plugin_internal_fault("no plugin bundle is installed"))?.wire_artifact_mutation_plan(request)
    }

    /// 📖️ This plugin's deterministic `contributor.list-artifact-mutations` roster: every owner
    /// document app's `SemanticMutation::kinds()` (`"<document-schema>#<kebab-kind>"`, committed by
    /// `PluginBuilder::document_app`/`::try_build`) plus every resolved `ArtifactContribution`'s
    /// mutations (`"<target-document-schema>#<plugin-id>:<kebab-kind>"`, committed by
    /// `PluginBuilder::try_build`/`ExtensionBundle::contributes`) — `crate::app::mutation_roster_entries`
    /// sorts by `mutation_id`, so repeated calls here never reorder or duplicate rows.
    pub async fn wire_list_artifact_mutations() -> Vec<u8> {
        encode_wire_serialized(&crate::app::mutation_roster_entries().await)
    }

    /// 🎯️ `contributor.artifact-mutation-plan`: decodes the target snapshot pack + contributor
    /// payload, runs the registered contribution's `CompositeMutationKind::plan` through a fresh
    /// `protocol::Planner`, and echoes `artifact_kind`/`mutation_id`/`revision`/`generation` back
    /// alongside the resulting `owner_ops`/`label`/`foreign` — mirrors `wire_artifact_infer`'s decode →
    /// validate-echo → execute → encode shape (`validate_wire_request_metadata`'s discipline, applied
    /// to `artifact_kind`/`mutation_id` instead of the inference metadata tuple: `crate::
    /// app::contributed_mutation_plan` rejects a request whose `artifact_kind` does not match the
    /// mutation's own registered target before ever touching the snapshot/payload bytes).
    pub async fn wire_artifact_mutation_plan(request: &[u8]) -> Result<Vec<u8>, Fault> {
        let request: crate::app::WireArtifactMutationPlanRequest = decode_wire_serialized(request).await?;
        if request.mutation_id.trim().is_empty() {
            return Err(plugin_internal_fault("artifact-mutation-plan requires a non-empty mutation_id"));
        }
        let output = crate::app::contributed_mutation_plan(&request.mutation_id, &request.artifact_kind, &request.snapshot_pack, &request.payload).await.map_err(|error| plugin_internal_fault(error.to_string()))?;
        let result = crate::app::WireArtifactMutationPlanResult {
            artifact_kind: request.artifact_kind,
            mutation_id: request.mutation_id,
            revision: request.revision,
            generation: request.generation,
            owner_ops: output.owner_ops,
            label: output.label,
            foreign: output.foreign,
        };
        Ok(encode_wire_serialized(&result))
    }

    #[cfg(test)]
    include!("🧪️tests/🔬️plugin-runtime-contributed-mutation-wire/🦀️.rs");

    /// 🪪️ Preflights every runtime row before factory work and publishes its allocation-bound lifecycle together.
    pub(crate) async fn plugin_open_actor_instance<PA: PluginApp>(runtime: &PluginRuntime<PA>, request: semio_framework::kernel::ActorInstanceOpenRequest, app_id: &str, actor: &str) -> Result<(), Fault> {
        let actor = RuntimeActorAuthority::new(actor)?;
        let mut lifetimes = runtime.guest_lifetimes.try_borrow_mut().map_err(|_| plugin_internal_fault("lifecycle authority busy"))?;
        let slot = lifetimes.get_mut(request.instance_id).filter(|slot| slot.cell.matches_open(request)).ok_or_else(|| plugin_internal_fault("exact opening lifecycle missing"))?;
        if slot.native_created || slot.cell.owner().is_some() {
            return Err(plugin_internal_fault("native opening already captured"));
        }
        let mut instances = runtime.instances.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime instance authority busy"))?;
        let quarantine = runtime.close_quarantine.try_borrow().map_err(|_| plugin_internal_fault("runtime quarantine authority busy"))?;
        let mut actors = runtime.instance_actors.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime actor authority busy"))?;
        let document_backbones = runtime.document_backbones.try_borrow().map_err(|_| plugin_internal_fault("document backbone binding authority busy"))?;
        if !instances.can_insert(request.instance_id) || !quarantine.can_insert(request.instance_id) || !actors.can_insert(request.instance_id) || !document_backbones.can_insert(request.instance_id) {
            return Err(plugin_internal_fault("native opening slot collided"));
        }
        if let Some(fault) = runtime.plugin_assembly_error.try_borrow().map_err(|_| plugin_internal_fault("plugin assembly authority busy"))?.clone() {
            return Err(fault);
        }
        let program = runtime.plugin.try_borrow().map_err(|_| plugin_internal_fault("plugin factory authority busy"))?;
        let program = program.as_ref().ok_or_else(|| plugin_internal_fault("plugin not initialized"))?;
        let mut app = program.create_app(app_id).ok_or_else(|| plugin_internal_fault("unknown app"))?;
        resolve_ready(app.bind_instance_id(request.instance_id));
        let cell = std::sync::Arc::new(RuntimeAppCell::new(AppInstance { id: request.instance_id, app, surface_contexts: Default::default() }));
        let lease = PluginInstanceCloseLease::from_cell(request.instance_id, &cell);
        let owner = crate::reactor::instance_lifetime::NativeLifetimeOwner::from_lease(slot.cell.lifetime(), lease).expect("preflighted exact native lifetime");
        slot.cell.install_owner(owner).unwrap_or_else(|_| panic!("preflighted opening owner slot"));
        instances.insert_admitted(request.instance_id, cell);
        actors.insert_admitted(request.instance_id, actor);
        slot.native_created = true;
        Ok(())
    }

    pub async fn plugin_create_app<PA: PluginApp>(runtime: &PluginRuntime<PA>, app_id: &str) -> Result<u32, Fault> {
        plugin_create_app_with_id(runtime, NEXT_INSTANCE_ID.fetch_add(1, Ordering::SeqCst), app_id).await
    }

    /// 🧬️ A2 (design-abi.md §2): `Event::InstanceOpen` carries a host-assigned `PluginInstanceId`
    /// (WIT `instance-id`) — the actor no longer allocates its own; it must open the app under
    /// EXACTLY the id the host names. `⚛️reactor::poll`'s `InstanceOpen` routing calls this instead
    /// of `plugin_create_app`. `plugin_create_app` (unchanged signature, still used by every
    /// pre-existing caller) now delegates here with a locally-allocated id, so nothing observing
    /// its old auto-increment behavior breaks.
    pub async fn plugin_create_app_with_id<PA: PluginApp>(runtime: &PluginRuntime<PA>, id: u32, app_id: &str) -> Result<u32, Fault> {
        if let Some(fault) = runtime.plugin_assembly_error.borrow().clone() {
            return Err(fault);
        }
        if !runtime.instances.try_borrow().map_err(|_| plugin_internal_fault("runtime instance authority is busy"))?.can_insert(id)
            || !runtime.close_quarantine.try_borrow().map_err(|_| plugin_internal_fault("runtime close quarantine is busy"))?.can_insert(id)
        {
            return Err(plugin_internal_fault(format!("fixed instance authority is saturated, collided, or quarantined: {id}")));
        }
        {
            let program = runtime.plugin.borrow();
            let program = program.as_ref().ok_or_else(|| plugin_internal_fault("plugin not initialized"))?;
            // 🌉️ `slot.borrow()` is a `Ref` from `LocalKey::with`'s sync `FnOnce(&T) -> R` closure,
            // which cannot itself be `async` — bridged via `resolve_ready` exactly like every other
            // E4/E5-adjacent sync-context call in this file (`Plugin::create_app`'s body does no real
            // awaiting; see the framework io module's `resolve_ready` doc comment).
            let mut app = program.create_app(app_id).ok_or_else(|| plugin_internal_fault(format!("unknown app: {app_id}")))?;
            resolve_ready(app.bind_instance_id(id));
            resolve_ready(with_instances_mut(runtime, |list| {
                list.insert_admitted(id, std::sync::Arc::new(RuntimeAppCell::new(AppInstance { id, app, surface_contexts: Default::default() })));
                Ok(())
            }))?;
            Ok(id)
        }
    }

    const RUNTIME_CLOSE_ITEMS_PER_STEP: usize = 1;
    const RUNTIME_CLOSE_BYTES_PER_STEP: usize = 4_096;
    const RUNTIME_CLOSE_INNER_GRANT_US: u64 = 2_000;
    const RUNTIME_CLOSE_ZERO_PROGRESS_LIMIT: u8 = 8;

    struct RuntimeLiveCleanupPump<PA: PluginApp> {
        session: Option<semio_framework_job::BatchJobSession<RuntimeLiveCleanupJob<PA>>>,
        rejected: Option<semio_framework_job::WorkerJobSessionAdmissionRejected<RuntimeLiveCleanupJob<PA>>>,
        outcome: Option<semio_framework_job::StepOutcome>,
        terminal: bool,
        pending_status: RuntimeMaintenanceStatus,
        closing: bool,
        faulted: bool,
    }

    impl<PA: PluginApp> RuntimeLiveCleanupPump<PA> {
        fn new() -> Self {
            Self { session: None, rejected: None, outcome: None, terminal: false, pending_status: RuntimeMaintenanceStatus::Ready, closing: false, faulted: false }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            self.closing = true;
            if let Some(outcome) = self.outcome.as_mut() {
                let step = outcome.close_step(maximum_items, maximum_bytes);
                if outcome.terminal_is_empty() {
                    self.outcome = None;
                }
                return match step {
                    semio_framework_job::JobPayloadCloseStep::Pending { released_items, released_bytes } => semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes },
                    semio_framework_job::JobPayloadCloseStep::Complete => semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 },
                };
            }
            if let Some(rejected) = self.rejected.as_mut() {
                let step = rejected.close_step(maximum_items, maximum_bytes);
                if rejected.terminal_is_empty() {
                    self.rejected = None;
                }
                return step;
            }
            if let Some(session) = self.session.as_mut() {
                session.begin_close();
                let step = session.close_step(maximum_items, maximum_bytes);
                if session.terminal_is_empty() {
                    self.session = None;
                }
                return match step {
                    semio_framework_job::WorkerJobCloseStep::Pending { released_items, released_bytes } => semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes },
                    semio_framework_job::WorkerJobCloseStep::Blocked => semio_framework_job::InteractiveJobCloseStep::Blocked,
                    semio_framework_job::WorkerJobCloseStep::Complete => semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 },
                };
            }
            semio_framework_job::InteractiveJobCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.closing && self.session.is_none() && self.rejected.is_none() && self.outcome.is_none()
        }
    }

    struct RuntimeCloseCleanupPump<PA: PluginApp> {
        session: Option<semio_framework_job::BatchJobSession<RuntimeCloseCleanupJob<PA>>>,
        rejected: Option<semio_framework_job::WorkerJobSessionAdmissionRejected<RuntimeCloseCleanupJob<PA>>>,
        outcome: Option<semio_framework_job::StepOutcome>,
        terminal: bool,
        complete: bool,
        blocked: bool,
        pending_status: RuntimeCloseStatus,
        faulted: bool,
    }

    impl<PA: PluginApp> RuntimeCloseCleanupPump<PA> {
        fn new() -> Self {
            Self { session: None, rejected: None, outcome: None, terminal: false, complete: false, blocked: false, pending_status: RuntimeCloseStatus::Ready, faulted: false }
        }
    }

    struct RuntimeLiveCleanupJob<PA: PluginApp> {
        instance_id: u32,
        cell: Option<std::sync::Weak<RuntimeAppCell<PA>>>,
        progress: Option<crate::app::PluginCloseStep>,
        contended: bool,
        closing: bool,
    }

    impl<PA: PluginApp> semio_framework_job::InteractiveJob for RuntimeLiveCleanupJob<PA> {
        fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
            cx.set_stage("plugin-runtime-live-cleanup");
            self.progress = None;
            self.contended = false;
            if cx.is_cancelled() {
                return semio_framework_job::StepOutcome::Cancelled;
            }
            let Some(cell) = self.cell.as_ref().and_then(std::sync::Weak::upgrade) else {
                return semio_framework_job::StepOutcome::Cancelled;
            };
            let mut instance = match cell.instance.try_lock() {
                Ok(instance) => instance,
                Err(std::sync::TryLockError::WouldBlock) => {
                    self.contended = true;
                    return semio_framework_job::StepOutcome::Yield;
                }
                Err(std::sync::TryLockError::Poisoned(_)) => {
                    return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin live cleanup authority is poisoned") });
                }
            };
            cx.consume_fuel(1);
            #[cfg(any(test, target_arch = "wasm32"))]
            cell.maintenance_probe_entries.fetch_add(1, Ordering::Relaxed);
            let traced = semio_framework_trace::runtime_diagnostics_enabled();
            let maintenance_started_us = traced.then(semio_framework_job::default_now_us).flatten();
            let maintenance = instance.app.maintenance_step(1, RUNTIME_CLOSE_BYTES_PER_STEP);
            if let (Some(started_us), Some(finished_us)) = (maintenance_started_us, maintenance_started_us.and_then(|_| semio_framework_job::default_now_us())) {
                if finished_us.saturating_sub(started_us) >= 2_000 {
                    eprintln!("[DEBUG] maintenance stage={} elapsed_us={} outcome={:?}", crate::app::LAST_MAINTENANCE_STAGE.load(Ordering::Relaxed), finished_us - started_us, maintenance.as_ref().map(|_| ()).map_err(|fault| fault.message.clone()));
                }
            }
            match maintenance {
                Ok(progress @ crate::app::PluginCloseStep::Pending { released_items, released_bytes }) if released_items <= 1 && released_bytes <= RUNTIME_CLOSE_BYTES_PER_STEP => {
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::CheckpointReady(semio_framework_job::Checkpoint {
                        state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CheckpointState, &self.instance_id.to_le_bytes()),
                        applied_progress: released_items as u64,
                    })
                }
                Ok(crate::app::PluginCloseStep::Pending { .. }) => {
                    semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin live cleanup step exceeded its exact item or byte contract") })
                }
                Ok(progress @ crate::app::PluginCloseStep::Blocked { .. }) => {
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::Yield
                }
                Ok(progress @ crate::app::PluginCloseStep::AwaitingInput { .. }) => {
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::Yield
                }
                Ok(crate::app::PluginCloseStep::Complete) => {
                    self.progress = Some(crate::app::PluginCloseStep::Complete);
                    semio_framework_job::StepOutcome::Complete(semio_framework_job::CommitCandidate {
                        state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CommitState, &self.instance_id.to_le_bytes()),
                        output: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitOutput),
                    })
                }
                Err(error) => semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, error.message.as_bytes()) }),
            }
        }

        fn begin_close(&mut self) {
            self.closing = true;
        }

        fn close_step(&mut self, maximum_items: usize, _maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            self.closing = true;
            if self.cell.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.cell.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            semio_framework_job::InteractiveJobCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.closing && self.cell.is_none()
        }
    }

    fn runtime_live_cleanup_nonterminal_status(contended: bool, progress: Option<crate::app::PluginCloseStep>, stalled_steps: &AtomicU32) -> RuntimeMaintenanceStatus {
        if contended {
            return RuntimeMaintenanceStatus::Ready;
        }
        if matches!(progress, Some(crate::app::PluginCloseStep::AwaitingInput { .. })) {
            stalled_steps.store(0, Ordering::SeqCst);
            return RuntimeMaintenanceStatus::Ready;
        }
        let zero_progress = matches!(progress, Some(crate::app::PluginCloseStep::Pending { released_items: 0, released_bytes: 0 } | crate::app::PluginCloseStep::Blocked { .. }));
        if !zero_progress {
            stalled_steps.store(0, Ordering::SeqCst);
            return RuntimeMaintenanceStatus::Ready;
        }
        let stalled = stalled_steps.fetch_add(1, Ordering::SeqCst).saturating_add(1);
        if stalled >= RUNTIME_MAINTENANCE_ZERO_PROGRESS_LIMIT {
            RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::ZeroProgress)
        } else {
            RuntimeMaintenanceStatus::Ready
        }
    }

    /// ⏱️ Publishes one maintenance turn: the measured wall cost is recorded next to the status so
    /// the decode site can name the overrun in microseconds, and a clock failure or a ceiling
    /// overrun outranks whatever the pump itself concluded.
    fn runtime_live_cleanup_publish_turn<PA: PluginApp>(cell: &RuntimeAppCell<PA>, status: RuntimeMaintenanceStatus, elapsed: Result<u64, RuntimeCleanupFault>) {
        let verdict = match elapsed {
            Err(cause) => RuntimeMaintenanceStatus::Fault(cause),
            Ok(elapsed_us) if semio_framework_trace::interactive_step_contract_violated(elapsed_us) => {
                if semio_framework_trace::runtime_diagnostics_enabled() {
                    eprintln!("[DEBUG] cooperative maintenance callback overran the interactive ceiling for instance {} (elapsed {elapsed_us}us) — recorded, not fatal: the callback clock measures wall time including descheduling and the pumped foreign job step; the job-level step contract quarantines slow steps", cell.id);
                }
                status
            }
            Ok(_) => status,
        };
        cell.maintenance_fault_us.store(elapsed.unwrap_or(RUNTIME_CLEANUP_UNMEASURED_US), Ordering::SeqCst);
        cell.maintenance_status.store(verdict.repr(), Ordering::SeqCst);
    }

    fn run_runtime_live_cleanup_turn<PA: PluginApp + 'static>(cell: &std::sync::Arc<RuntimeAppCell<PA>>, generation: semio_framework_job::Generation) {
        let mut now_us = semio_framework_job::default_now_us;
        let clock = runtime_callback_clock_begin(&mut now_us);
        if cell.maintenance_status.compare_exchange(RuntimeMaintenanceStatus::Queued.repr(), RuntimeMaintenanceStatus::Running.repr(), Ordering::SeqCst, Ordering::SeqCst).is_err() {
            return;
        }
        let clock = match clock {
            Ok(clock) => clock,
            Err(cause) => return runtime_live_cleanup_publish_turn(cell, RuntimeMaintenanceStatus::Ready, Err(cause)),
        };
        let status = match cell.maintenance_pump.try_lock() {
            Ok(mut pump) => runtime_live_cleanup_pump_one(cell, generation, &mut pump),
            Err(_) => RuntimeMaintenanceStatus::Ready,
        };
        runtime_live_cleanup_publish_turn(cell, status, runtime_callback_clock_elapsed(&mut now_us, clock));
    }

    fn runtime_live_cleanup_pump_one<PA: PluginApp + 'static>(cell: &std::sync::Arc<RuntimeAppCell<PA>>, generation: semio_framework_job::Generation, pump: &mut RuntimeLiveCleanupPump<PA>) -> RuntimeMaintenanceStatus {
        if pump.closing {
            let _ = pump.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::AlreadyClosing);
        }
        if let Some(rejected) = pump.rejected.as_mut() {
            let _ = rejected.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            if rejected.terminal_is_empty() {
                pump.rejected = None;
                return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::AdmissionRejected);
            }
            return RuntimeMaintenanceStatus::Ready;
        }
        if let Some(outcome) = pump.outcome.as_mut() {
            let _ = outcome.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            if !outcome.terminal_is_empty() {
                return RuntimeMaintenanceStatus::Ready;
            }
            pump.outcome = None;
            if pump.terminal {
                if let Some(session) = pump.session.as_mut() {
                    session.begin_close();
                }
            } else if pump.session.as_mut().is_some_and(|session| session.resume().is_err()) {
                return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::Resume);
            } else {
                return pump.pending_status;
            }
        }
        if pump.terminal {
            let Some(session) = pump.session.as_mut() else {
                pump.terminal = false;
                return pump.pending_status;
            };
            let _ = session.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            if session.terminal_is_empty() {
                pump.session = None;
                pump.terminal = false;
                return if pump.faulted { RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::PriorOutcome) } else { pump.pending_status };
            }
            return RuntimeMaintenanceStatus::Ready;
        }
        if pump.session.is_none() {
            let job = RuntimeLiveCleanupJob { instance_id: cell.id, cell: Some(std::sync::Arc::downgrade(cell)), progress: None, contended: false, closing: false };
            let params = semio_framework_job::BatchJobParams {
                operation: semio_framework_job::OperationId((1u64 << 62) | cell.id as u64),
                generation,
                cancel: semio_framework_job::CancelToken::root_now(),
                config: semio_framework_job::BatchDriveConfig { site: "plugin_runtime_live_cleanup", stage: semio_framework_job::InteractiveStage::InteractiveStep, fuel_per_step: 1, step_budget_us: RUNTIME_CLOSE_INNER_GRANT_US },
                now_us: semio_framework_job::default_now_us,
            };
            match semio_framework_job::BatchJobSession::try_new(job, params) {
                Ok(session) => pump.session = Some(session),
                Err(rejected) => {
                    pump.rejected = Some(rejected);
                    return RuntimeMaintenanceStatus::Ready;
                }
            }
        }
        let Some(session) = pump.session.as_mut() else { return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::MissingSession) };
        if session.step().is_err() {
            return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::AbiMismatch);
        }
        if !session.checkout_outcome() {
            return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::Checkout);
        }
        let Some(job) = session.checked_out_job_mut() else { return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::CheckedOutJob) };
        pump.pending_status = runtime_live_cleanup_nonterminal_status(job.contended, job.progress, &cell.maintenance_stalled_steps);
        #[cfg(test)]
        if matches!(job.progress, Some(crate::app::PluginCloseStep::AwaitingInput { .. })) {
            cell.maintenance_probe_input_waits.fetch_add(1, Ordering::SeqCst);
        }
        let Some(outcome) = session.take_outcome() else { return RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::TakeOutcome) };
        pump.terminal = outcome.is_terminal();
        let faulted = matches!(outcome, semio_framework_job::StepOutcome::Fault(_) | semio_framework_job::StepOutcome::Cancelled);
        pump.faulted = faulted;
        pump.outcome = Some(outcome);
        RuntimeMaintenanceStatus::Ready
    }

    struct RuntimeCloseCleanupJob<PA: PluginApp> {
        state: Option<std::sync::Weak<RuntimeCloseWorkerState<PA>>>,
        progress: Option<crate::app::PluginCloseStep>,
        contended: bool,
        closing: bool,
    }

    impl<PA: PluginApp> semio_framework_job::InteractiveJob for RuntimeCloseCleanupJob<PA> {
        fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
            let Some(state) = self.state.as_ref().and_then(std::sync::Weak::upgrade) else {
                return semio_framework_job::StepOutcome::Cancelled;
            };
            runtime_close_phase(&state, 8);
            cx.set_stage("plugin-runtime-close-cleanup");
            runtime_close_phase(&state, 9);
            self.progress = None;
            self.contended = false;
            if cx.is_cancelled() {
                return semio_framework_job::StepOutcome::Cancelled;
            }
            let cell = {
                let cell = match state.cell.try_lock() {
                    Ok(cell) => cell,
                    Err(std::sync::TryLockError::WouldBlock) => {
                        self.contended = true;
                        return semio_framework_job::StepOutcome::Yield;
                    }
                    Err(std::sync::TryLockError::Poisoned(_)) => {
                        return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin close cell authority is poisoned") });
                    }
                };
                let Some(cell) = cell.as_ref() else {
                    self.progress = Some(crate::app::PluginCloseStep::Complete);
                    return semio_framework_job::StepOutcome::Complete(semio_framework_job::CommitCandidate {
                        state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CommitState, &state.instance_id.to_le_bytes()),
                        output: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitOutput),
                    });
                };
                cell.clone()
            };
            {
                let mut maintenance = match cell.maintenance_pump.try_lock() {
                    Ok(maintenance) => maintenance,
                    Err(std::sync::TryLockError::WouldBlock) => {
                        self.contended = true;
                        return semio_framework_job::StepOutcome::Yield;
                    }
                    Err(std::sync::TryLockError::Poisoned(_)) => {
                        return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin maintenance session authority is poisoned") });
                    }
                };
                runtime_close_phase(&state, 10);
                let progress = maintenance.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
                runtime_close_phase(&state, 11);
                match progress {
                    semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => {
                        self.progress = Some(crate::app::PluginCloseStep::Pending { released_items, released_bytes });
                    }
                    semio_framework_job::InteractiveJobCloseStep::Blocked => self.contended = true,
                    semio_framework_job::InteractiveJobCloseStep::Complete => {}
                }
                if !maintenance.terminal_is_empty() {
                    cx.consume_fuel(1);
                    return semio_framework_job::StepOutcome::Yield;
                }
            }
            let mut instance = match cell.instance.try_lock() {
                Ok(instance) => instance,
                Err(std::sync::TryLockError::WouldBlock) => {
                    self.contended = true;
                    return semio_framework_job::StepOutcome::Yield;
                }
                Err(std::sync::TryLockError::Poisoned(_)) => {
                    return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin app close authority is poisoned") });
                }
            };
            cx.consume_fuel(1);
            runtime_close_phase(&state, 12);
            #[cfg(test)]
            state.physical_close_calls.fetch_add(1, Ordering::SeqCst);
            let progress = instance.app.close_step(RUNTIME_CLOSE_ITEMS_PER_STEP, RUNTIME_CLOSE_BYTES_PER_STEP);
            runtime_close_phase(&state, 13);
            let outcome = match progress {
                Ok(progress @ crate::app::PluginCloseStep::Pending { released_items, released_bytes }) if released_items <= RUNTIME_CLOSE_ITEMS_PER_STEP && released_bytes <= RUNTIME_CLOSE_BYTES_PER_STEP => {
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::CheckpointReady(semio_framework_job::Checkpoint {
                        state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CheckpointState, &state.instance_id.to_le_bytes()),
                        applied_progress: released_items as u64,
                    })
                }
                Ok(crate::app::PluginCloseStep::Pending { .. }) => {
                    semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin close step exceeded its item or byte contract") })
                }
                Ok(progress @ crate::app::PluginCloseStep::Blocked { reason }) => {
                    runtime_close_pending_authority(reason);
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::Yield
                }
                Ok(progress @ crate::app::PluginCloseStep::AwaitingInput { reason }) => {
                    runtime_close_pending_authority(reason);
                    self.progress = Some(progress);
                    semio_framework_job::StepOutcome::Yield
                }
                Ok(crate::app::PluginCloseStep::Complete) => {
                    if !instance.app.close_terminal_is_empty() {
                        return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault {
                            detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"plugin close reported Complete without a terminal-empty app witness"),
                        });
                    }
                    self.progress = Some(crate::app::PluginCloseStep::Complete);
                    semio_framework_job::StepOutcome::Complete(semio_framework_job::CommitCandidate {
                        state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CommitState, &state.instance_id.to_le_bytes()),
                        output: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitOutput),
                    })
                }
                Err(error) => semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, error.message.as_bytes()) }),
            };
            runtime_close_phase(&state, 14);
            outcome
        }

        fn begin_close(&mut self) {
            self.closing = true;
        }

        fn close_step(&mut self, maximum_items: usize, _maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            self.closing = true;
            if self.state.is_some() {
                if maximum_items == 0 {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                drop(self.state.take());
                return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            semio_framework_job::InteractiveJobCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.closing && self.state.is_none()
        }
    }

    fn runtime_close_pool() -> semio_framework_async::WorkerPool {
        let cores = std::thread::available_parallelism().map_or(1, std::num::NonZeroUsize::get);
        semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative, cores))
    }

    fn runtime_close_nonterminal_status(contended: bool, progress: Option<crate::app::PluginCloseStep>, stalled_steps: &AtomicU8) -> RuntimeCloseStatus {
        if contended {
            return RuntimeCloseStatus::Ready;
        }
        if matches!(progress, Some(crate::app::PluginCloseStep::Blocked { .. } | crate::app::PluginCloseStep::AwaitingInput { .. })) {
            stalled_steps.swap(0, Ordering::SeqCst);
            return RuntimeCloseStatus::ExternalWait;
        }
        let zero_progress = matches!(progress, Some(crate::app::PluginCloseStep::Pending { released_items: 0, released_bytes: 0 })) || progress.is_none();
        let stalled = if zero_progress {
            stalled_steps.fetch_add(1, Ordering::SeqCst).saturating_add(1)
        } else {
            stalled_steps.swap(0, Ordering::SeqCst);
            0
        };
        if stalled >= RUNTIME_CLOSE_ZERO_PROGRESS_LIMIT {
            RuntimeCloseStatus::Fault(RuntimeCleanupFault::ZeroProgress)
        } else {
            RuntimeCloseStatus::Ready
        }
    }

    fn run_runtime_close_turn_inner<PA: PluginApp + 'static>(state: &std::sync::Arc<RuntimeCloseWorkerState<PA>>) -> Option<RuntimeCloseStatus> {
        if state.status.compare_exchange(RuntimeCloseStatus::Queued.repr(), RuntimeCloseStatus::Running.repr(), Ordering::SeqCst, Ordering::SeqCst).is_err() {
            return None;
        }
        let retained = state.deadline_resume.load(Ordering::SeqCst);
        if retained != u8::MAX {
            return Some(RuntimeCloseStatus::from_repr(retained));
        }
        #[cfg(test)]
        {
            state.callback_phase_started_us.store(semio_framework_job::default_now_us().unwrap_or(0), Ordering::SeqCst);
            for elapsed in &state.callback_phase_us {
                elapsed.store(0, Ordering::SeqCst);
            }
        }
        let status = match state.pump.try_lock() {
            Ok(mut pump) => {
                let status = runtime_close_cleanup_pump_one(state, &mut pump);
                runtime_close_phase(state, 20);
                drop(pump);
                runtime_close_phase(state, 21);
                status
            }
            Err(_) => RuntimeCloseStatus::Ready,
        };
        runtime_close_phase(state, 6);
        let candidate = if status == RuntimeCloseStatus::Complete { runtime_close_retire_cell(state) } else { status };
        runtime_close_phase(state, 7);
        Some(candidate)
    }

    fn runtime_close_retire_cell<PA: PluginApp>(state: &RuntimeCloseWorkerState<PA>) -> RuntimeCloseStatus {
        let mut owner = match state.cell.try_lock() {
            Ok(owner) => owner,
            Err(std::sync::TryLockError::WouldBlock) => return RuntimeCloseStatus::Ready,
            Err(std::sync::TryLockError::Poisoned(_)) => return runtime_close_fault(state, RuntimeCleanupFault::OwnerPoisoned),
        };
        let Some(cell) = owner.as_ref() else { return RuntimeCloseStatus::Complete };
        {
            let instance = match cell.instance.try_lock() {
                Ok(instance) => instance,
                Err(std::sync::TryLockError::WouldBlock) => return RuntimeCloseStatus::Ready,
                Err(std::sync::TryLockError::Poisoned(_)) => return runtime_close_fault(state, RuntimeCleanupFault::InstancePoisoned),
            };
            if !instance.app.close_terminal_is_empty() {
                return runtime_close_fault(state, RuntimeCleanupFault::InstanceNotDrained);
            }
            let maintenance = match cell.maintenance_pump.try_lock() {
                Ok(maintenance) => maintenance,
                Err(std::sync::TryLockError::WouldBlock) => return RuntimeCloseStatus::Ready,
                Err(std::sync::TryLockError::Poisoned(_)) => return runtime_close_fault(state, RuntimeCleanupFault::MaintenancePoisoned),
            };
            if !maintenance.terminal_is_empty() {
                return runtime_close_fault(state, RuntimeCleanupFault::MaintenanceNotDrained);
            }
        }
        let detached = owner.take().expect("captured owner remains under the same guard");
        match std::sync::Arc::try_unwrap(detached) {
            Ok(cell) => {
                drop(cell);
                RuntimeCloseStatus::Complete
            }
            Err(detached) => {
                **owner = Some(detached);
                RuntimeCloseStatus::ExternalWait
            }
        }
    }

    /// ⏳️ A close authority that is not yet releasable is a WAIT, never a fault: the ladder keeps
    /// stepping until its external owner lets go (mirrors the live cleanup job, which has always
    /// yielded on `Blocked`). Reported on a doubling cadence so a genuinely stuck owner is visible
    /// without flooding a close that clears after a few turns.
    fn runtime_close_pending_authority(reason: &'static str) {
        let seen = RUNTIME_CLOSE_PENDING_AUTHORITY_TURNS.fetch_add(1, Ordering::Relaxed).saturating_add(1);
        if seen.is_power_of_two() {
            debug_runtime_line(format_args!("[DEBUG] runtime close pending authority turn={seen} reason={reason}"));
        }
    }

    static RUNTIME_CLOSE_PENDING_AUTHORITY_TURNS: AtomicU64 = AtomicU64::new(0);

    fn runtime_close_fault<PA: PluginApp>(state: &RuntimeCloseWorkerState<PA>, cause: RuntimeCleanupFault) -> RuntimeCloseStatus {
        #[cfg(test)]
        state.last_fault_origin.store(cause as u8, Ordering::SeqCst);
        #[cfg(not(test))]
        let _ = state;
        RuntimeCloseStatus::Fault(cause)
    }

    fn runtime_close_phase<PA: PluginApp>(state: &RuntimeCloseWorkerState<PA>, phase: usize) {
        #[cfg(test)]
        if let Some(now) = semio_framework_job::default_now_us() {
            state.callback_phase_us[phase].store(now.saturating_sub(state.callback_phase_started_us.load(Ordering::SeqCst)), Ordering::SeqCst);
        }
        #[cfg(not(test))]
        let _ = (state, phase);
    }

    fn runtime_close_cleanup_pump_one<PA: PluginApp + 'static>(state: &std::sync::Arc<RuntimeCloseWorkerState<PA>>, pump: &mut RuntimeCloseCleanupPump<PA>) -> RuntimeCloseStatus {
        runtime_close_phase(state, 0);
        if let Some(rejected) = pump.rejected.as_mut() {
            let _ = rejected.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            runtime_close_phase(state, 5);
            if rejected.terminal_is_empty() {
                pump.rejected = None;
                return runtime_close_fault(state, RuntimeCleanupFault::AdmissionRejected);
            }
            return RuntimeCloseStatus::Ready;
        }
        if let Some(outcome) = pump.outcome.as_mut() {
            let _ = outcome.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            runtime_close_phase(state, 5);
            runtime_close_phase(state, 15);
            let terminal = outcome.terminal_is_empty();
            runtime_close_phase(state, 16);
            if !terminal {
                return RuntimeCloseStatus::Ready;
            }
            pump.outcome = None;
            runtime_close_phase(state, 17);
            if pump.terminal {
                if let Some(session) = pump.session.as_mut() {
                    session.begin_close();
                }
            } else {
                runtime_close_phase(state, 18);
                let failed = pump.session.as_mut().is_some_and(|session| session.resume().is_err());
                runtime_close_phase(state, 19);
                return if failed { runtime_close_fault(state, RuntimeCleanupFault::Resume) } else { pump.pending_status };
            }
        }
        if pump.terminal {
            let Some(session) = pump.session.as_mut() else { return runtime_close_fault(state, RuntimeCleanupFault::MissingSession) };
            let _ = session.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            runtime_close_phase(state, 5);
            if !session.terminal_is_empty() {
                return RuntimeCloseStatus::Ready;
            }
            pump.session = None;
            pump.terminal = false;
            if pump.faulted {
                return runtime_close_fault(state, RuntimeCleanupFault::PriorOutcome);
            }
            if pump.blocked {
                return RuntimeCloseStatus::ExternalWait;
            }
            if pump.complete {
                return RuntimeCloseStatus::Complete;
            }
            return pump.pending_status;
        }
        if pump.session.is_none() {
            runtime_close_phase(state, 1);
            let job = RuntimeCloseCleanupJob { state: Some(std::sync::Arc::downgrade(state)), progress: None, contended: false, closing: false };
            let params = semio_framework_job::BatchJobParams {
                operation: semio_framework_job::OperationId((1u64 << 63) | state.instance_id as u64),
                generation: state.generation,
                cancel: semio_framework_job::CancelToken::root_now(),
                config: semio_framework_job::BatchDriveConfig { site: "plugin_runtime_close_cleanup", stage: semio_framework_job::InteractiveStage::InteractiveStep, fuel_per_step: 1, step_budget_us: RUNTIME_CLOSE_INNER_GRANT_US },
                now_us: semio_framework_job::default_now_us,
            };
            match semio_framework_job::BatchJobSession::try_new(job, params) {
                Ok(session) => pump.session = Some(session),
                Err(rejected) => {
                    pump.rejected = Some(rejected);
                    return RuntimeCloseStatus::Ready;
                }
            }
            runtime_close_phase(state, 2);
        }
        let Some(session) = pump.session.as_mut() else { return runtime_close_fault(state, RuntimeCleanupFault::MissingSession) };
        runtime_close_phase(state, 22);
        let stepped = session.step();
        runtime_close_phase(state, 23);
        if stepped.is_err() {
            return runtime_close_fault(state, RuntimeCleanupFault::AbiMismatch);
        }
        runtime_close_phase(state, 3);
        if !session.checkout_outcome() {
            return runtime_close_fault(state, RuntimeCleanupFault::Checkout);
        }
        let Some(job) = session.checked_out_job_mut() else { return runtime_close_fault(state, RuntimeCleanupFault::CheckedOutJob) };
        pump.complete = job.progress == Some(crate::app::PluginCloseStep::Complete);
        pump.blocked = matches!(job.progress, Some(crate::app::PluginCloseStep::Blocked { .. }));
        pump.pending_status = runtime_close_nonterminal_status(job.contended, job.progress, &state.stalled_steps);
        if let Some(cause) = pump.pending_status.cause() {
            runtime_close_fault(state, cause);
        }
        let Some(outcome) = session.take_outcome() else { return runtime_close_fault(state, RuntimeCleanupFault::TakeOutcome) };
        runtime_close_phase(state, 4);
        pump.terminal = outcome.is_terminal();
        let faulted = matches!(outcome, semio_framework_job::StepOutcome::Fault(_) | semio_framework_job::StepOutcome::Cancelled);
        pump.faulted = faulted;
        #[cfg(test)]
        if let semio_framework_job::StepOutcome::Fault(fault) = &outcome {
            if let Some(bytes) = fault.detail.single_page() {
                let mut last_fault = state.last_fault.lock().unwrap();
                let count = bytes.len().min(last_fault.len());
                last_fault[..count].copy_from_slice(&bytes[..count]);
            }
        }
        pump.outcome = Some(outcome);
        RuntimeCloseStatus::Ready
    }

    #[cfg(test)]
    include!("🧪️tests/🔬️plugin-runtime-runtime-close-budget/🦀️.rs");

    /// 🩺️ Language-neutral decode conformance: every declared cleanup-fault variant must round-trip
    /// through its status atom and produce exactly the fixture's wire code and message shape, so the
    /// React shell's classifier and this module can never drift apart silently.
    #[cfg(test)]
    include!("🧪️tests/🔬️plugin-runtime-runtime-cleanup-fault-vector/🦀️.rs");

    fn run_runtime_close_turn<PA: PluginApp + 'static>(state: &std::sync::Arc<RuntimeCloseWorkerState<PA>>) {
        run_runtime_close_turn_with_clock(state, semio_framework_job::default_now_us);
    }

    fn runtime_callback_clock_begin(now_us: &mut impl FnMut() -> Option<u64>) -> Result<(u64, u64), RuntimeCleanupFault> {
        let start = now_us().ok_or(RuntimeCleanupFault::Clock)?;
        let preflight = now_us().ok_or(RuntimeCleanupFault::Clock)?;
        if preflight < start {
            return Err(RuntimeCleanupFault::ClockRegression);
        }
        Ok((start, preflight))
    }

    fn runtime_callback_clock_elapsed(now_us: &mut impl FnMut() -> Option<u64>, (start, preflight): (u64, u64)) -> Result<u64, RuntimeCleanupFault> {
        let finished = now_us().ok_or(RuntimeCleanupFault::Clock)?;
        if finished < preflight {
            return Err(RuntimeCleanupFault::ClockRegression);
        }
        Ok(finished - start)
    }

    fn run_runtime_close_turn_with_clock<PA: PluginApp + 'static>(state: &std::sync::Arc<RuntimeCloseWorkerState<PA>>, mut now_us: impl FnMut() -> Option<u64>) {
        let clock = match runtime_callback_clock_begin(&mut now_us) {
            Ok(clock) => clock,
            Err(cause) => {
                if state.status.compare_exchange(RuntimeCloseStatus::Queued.repr(), RuntimeCloseStatus::Running.repr(), Ordering::SeqCst, Ordering::SeqCst).is_ok() {
                    state.last_callback_elapsed_us.store(u64::MAX, Ordering::SeqCst);
                    state.status.store(runtime_close_fault(state, cause).repr(), Ordering::SeqCst);
                }
                return;
            }
        };
        let Some(status) = run_runtime_close_turn_inner(state) else { return };
        let elapsed_us = match runtime_callback_clock_elapsed(&mut now_us, clock) {
            Ok(elapsed) => elapsed,
            Err(cause) => {
                state.last_callback_elapsed_us.store(u64::MAX, Ordering::SeqCst);
                state.status.store(runtime_close_fault(state, cause).repr(), Ordering::SeqCst);
                return;
            }
        };
        runtime_close_publish_turn(state, status, elapsed_us);
    }

    fn runtime_close_publish_turn<PA: PluginApp>(state: &RuntimeCloseWorkerState<PA>, status: RuntimeCloseStatus, elapsed_us: u64) {
        state.last_callback_elapsed_us.store(elapsed_us, Ordering::SeqCst);
        let verdict = if !matches!(status, RuntimeCloseStatus::Fault(_)) && semio_framework_trace::interactive_step_contract_violated(elapsed_us) {
            #[cfg(test)]
            debug_runtime_line(format_args!("[DEBUG] native close deadline instance={} generation={} candidate={status:?} elapsed_us={elapsed_us}", state.instance_id, state.generation.0));
            state.deadline_resume.store(status.repr(), Ordering::SeqCst);
            let _ = state.deadline_elapsed_us.compare_exchange(0, elapsed_us, Ordering::SeqCst, Ordering::SeqCst);
            RuntimeCloseStatus::DeadlineYield
        } else {
            state.deadline_resume.store(u8::MAX, Ordering::SeqCst);
            status
        };
        state.status.store(verdict.repr(), Ordering::SeqCst);
    }

    fn try_schedule_runtime_close<PA: PluginApp + 'static>(pool: &semio_framework_async::WorkerPool, state: &std::sync::Arc<RuntimeCloseWorkerState<PA>>) -> bool {
        if state.status.compare_exchange(RuntimeCloseStatus::Ready.repr(), RuntimeCloseStatus::Queued.repr(), Ordering::SeqCst, Ordering::SeqCst).is_err() {
            return false;
        }
        let scheduled_state = std::sync::Arc::downgrade(state);
        let scheduled_pool = pool.clone();
        let job: semio_framework_async::Job = Box::new(move || {
            let Some(scheduled_state) = scheduled_state.upgrade() else { return };
            run_runtime_close_turn(&scheduled_state);
            if scheduled_state.status.load(Ordering::SeqCst) == RuntimeCloseStatus::Ready.repr() {
                let _ = try_schedule_runtime_close(&scheduled_pool, &scheduled_state);
            }
        });
        match pool.try_submit(semio_framework_async::Lane::Maintenance, job) {
            Ok(()) => true,
            Err(error) => {
                state.status.compare_exchange(RuntimeCloseStatus::Queued.repr(), RuntimeCloseStatus::Ready.repr(), Ordering::SeqCst, Ordering::SeqCst).ok();
                drop(error.into_job());
                false
            }
        }
    }

    fn checked_runtime_close_generation(current: u64) -> Result<u64, Fault> {
        current.checked_add(1).ok_or_else(|| plugin_internal_fault("runtime close generation exhausted"))
    }

    pub async fn plugin_destroy_app<PA: PluginApp + 'static>(runtime: &PluginRuntime<PA>, instance_id: u32) -> Result<(), Fault> {
        plugin_begin_instance_close(runtime, instance_id, None).map(|_| ())
    }

    #[cfg(test)]
    std::thread_local! {
        static RUNTIME_CLOSE_CONSTRUCTION_LIVE: Cell<Option<bool>> = const { Cell::new(None) };
        static RUNTIME_CLOSE_CONSTRUCTION_FAIL: Cell<bool> = const { Cell::new(false) };
    }

    fn plugin_begin_instance_close<PA: PluginApp + 'static>(runtime: &PluginRuntime<PA>, instance_id: u32, expected: Option<&std::sync::Weak<RuntimeAppCell<PA>>>) -> Result<std::sync::Arc<RuntimeCloseWorkerState<PA>>, Fault> {
        let mut instances = runtime.instances.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime instance authority is busy"))?;
        let mut quarantine = runtime.close_quarantine.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime close quarantine is busy"))?;
        let mut actors = runtime.instance_actors.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime actor authority is busy"))?;
        let mut document_backbones = runtime.document_backbones.try_borrow_mut().map_err(|_| plugin_internal_fault("document backbone binding authority is busy"))?;
        if let Some(expected) = expected {
            let current = instances.get(instance_id).ok_or_else(|| plugin_internal_fault("captured app lifetime is no longer live"))?;
            if !std::sync::Weak::ptr_eq(expected, &std::sync::Arc::downgrade(current)) {
                return Err(plugin_internal_fault("captured app lifetime does not match the current instance"));
            }
        }
        if !quarantine.can_insert(instance_id) {
            return Err(plugin_internal_fault(format!("runtime close quarantine is saturated or collided: {instance_id}")));
        }
        let generation = checked_runtime_close_generation(runtime.close_generation.get())?;
        #[cfg(test)]
        let original_allocation = instances.get(instance_id).map(std::sync::Arc::as_ptr);
        let cell = instances.get(instance_id).cloned().ok_or_else(|| plugin_internal_fault(format!("unknown instance: {instance_id}")))?;
        #[cfg(test)]
        RUNTIME_CLOSE_CONSTRUCTION_FAIL.with(|fail| {
            if fail.replace(false) {
                panic!("injected before close worker allocation");
            }
        });
        let state = std::sync::Arc::new(RuntimeCloseWorkerState {
            instance_id,
            generation: semio_framework_job::Generation(generation),
            cell: std::sync::Mutex::new(std::mem::ManuallyDrop::new(Some(cell))),
            pump: std::sync::Mutex::new(RuntimeCloseCleanupPump::new()),
            status: AtomicU8::new(RuntimeCloseStatus::Ready.repr()),
            deadline_resume: AtomicU8::new(u8::MAX),
            deadline_elapsed_us: AtomicU64::new(0),
            stalled_steps: AtomicU8::new(0),
            last_callback_elapsed_us: AtomicU64::new(0),
            #[cfg(test)]
            last_fault: std::sync::Mutex::new([0; 256]),
            #[cfg(test)]
            last_fault_origin: AtomicU8::new(0),
            #[cfg(test)]
            physical_close_calls: AtomicU64::new(0),
            #[cfg(test)]
            callback_phase_started_us: AtomicU64::new(0),
            #[cfg(test)]
            callback_phase_us: std::array::from_fn(|_| AtomicU64::new(0)),
        });
        #[cfg(test)]
        RUNTIME_CLOSE_CONSTRUCTION_LIVE.with(|probe| probe.set(Some(original_allocation.is_some() && instances.get(instance_id).map(std::sync::Arc::as_ptr) == original_allocation)));
        quarantine.insert_admitted(instance_id, RuntimeCloseEntry { state: state.clone() });
        drop(instances.take(instance_id));
        runtime.close_generation.set(generation);
        let _ = actors.take(instance_id);
        if let Some(binding) = document_backbones.take(instance_id) {
            if let Some(owner) = binding.channel {
                owner.begin_retire().map_err(|error| plugin_internal_fault(error.to_string()))?;
            }
        }
        drop(document_backbones);
        drop(actors);
        drop(quarantine);
        drop(instances);
        let _ = try_schedule_runtime_close(&runtime_close_pool(), &state);
        Ok(state)
    }

    pub fn plugin_step_close_cleanup<PA: PluginApp + 'static>(runtime: &PluginRuntime<PA>) -> Result<bool, Fault> {
        let entry = runtime
            .close_quarantine
            .try_borrow()
            .map_err(|_| plugin_internal_fault("runtime close quarantine is busy"))?
            .next_entry_from(runtime.close_cleanup_cursor.get())
            .map(|(index, instance_id, entry)| (index, instance_id, entry.state.clone()));
        let Some((index, instance_id, state)) = entry else { return Ok(false) };
        runtime.close_cleanup_cursor.set((index + 1) % PLUGIN_RUNTIME_INSTANCE_SLOTS);
        match RuntimeCloseStatus::from_repr(state.status.load(Ordering::SeqCst)) {
            RuntimeCloseStatus::Complete => {
                let removed = runtime.close_quarantine.try_borrow_mut().map_err(|_| plugin_internal_fault("runtime close quarantine is busy"))?.take(instance_id);
                drop(removed);
                Ok(true)
            }
            RuntimeCloseStatus::Fault(cause) => Err(runtime_cleanup_fault("close", cause, instance_id, state.last_callback_elapsed_us.load(Ordering::SeqCst))),
            status @ (RuntimeCloseStatus::ExternalWait | RuntimeCloseStatus::DeadlineYield) => {
                if state.status.compare_exchange(status.repr(), RuntimeCloseStatus::Ready.repr(), Ordering::SeqCst, Ordering::SeqCst).is_err() {
                    return Ok(false);
                }
                Ok(try_schedule_runtime_close(&runtime_close_pool(), &state))
            }
            status => {
                let pool = runtime_close_pool();
                let scheduled = status == RuntimeCloseStatus::Ready && try_schedule_runtime_close(&pool, &state);
                #[cfg(target_arch = "wasm32")]
                if let Some(now_ms) = semio_framework_job::default_now_ms() {
                    pool.pump(now_ms);
                }
                Ok(scheduled || status == RuntimeCloseStatus::Queued || status == RuntimeCloseStatus::Running)
            }
        }
    }

    #[cfg(target_arch = "wasm32")]
    fn pump_runtime_live_cooperative_turn<PA: PluginApp>(cell: &RuntimeAppCell<PA>) -> Result<(), Fault> {
        let before = cell.maintenance_status.load(Ordering::SeqCst);
        let turn = cell.maintenance_probe_turns.load(Ordering::Relaxed).saturating_add(1);
        cell.maintenance_probe_turns.store(turn, Ordering::Relaxed);
        let pool = runtime_close_pool();
        let now_ms = semio_framework_job::default_now_ms();
        if let Some(now_ms) = now_ms {
            pool.pump(now_ms);
        } else {
            cell.maintenance_fault_us.store(RUNTIME_CLEANUP_UNMEASURED_US, Ordering::SeqCst);
            cell.maintenance_status.store(RuntimeMaintenanceStatus::Fault(RuntimeCleanupFault::CooperativeClock).repr(), Ordering::SeqCst);
        }
        if turn <= 4096 && turn.is_power_of_two() && semio_framework_trace::runtime_diagnostics_enabled() {
            let phase = cell
                .maintenance_pump
                .try_lock()
                .ok()
                .map(|pump| u8::from(pump.session.is_some()) | (u8::from(pump.outcome.is_some()) << 1) | (u8::from(pump.rejected.is_some()) << 2) | (u8::from(pump.closing) << 3) | (u8::from(pump.faulted) << 4) | (u8::from(pump.terminal) << 5));
            eprintln!(
                "[DEBUG] cooperative-maintenance instance={} turn={} generation={} status={}->{} entries={} phase={:?} clock={} pool={:?}",
                cell.id,
                turn,
                cell.maintenance_generation.load(Ordering::SeqCst),
                before,
                cell.maintenance_status.load(Ordering::SeqCst),
                cell.maintenance_probe_entries.load(Ordering::Relaxed),
                phase,
                now_ms.is_some(),
                pool.try_cooperative_snapshot()
            );
        }
        now_ms.map(|_| ()).ok_or_else(|| runtime_cleanup_fault("live", RuntimeCleanupFault::CooperativeClock, cell.id, RUNTIME_CLEANUP_UNMEASURED_US))
    }

    pub fn plugin_step_live_cleanup<PA: PluginApp + 'static>(runtime: &PluginRuntime<PA>) -> Result<bool, Fault> {
        let cell = runtime.instances.try_borrow().map_err(|_| plugin_internal_fault("runtime instance authority is busy"))?.next_entry_from(runtime.live_cleanup_cursor.get()).map(|(index, _, cell)| (index, cell.clone()));
        let Some((index, cell)) = cell else { return Ok(false) };
        runtime.live_cleanup_cursor.set((index + 1) % PLUGIN_RUNTIME_INSTANCE_SLOTS);
        match RuntimeMaintenanceStatus::from_repr(cell.maintenance_status.load(Ordering::SeqCst)) {
            RuntimeMaintenanceStatus::Fault(cause) => Err(runtime_cleanup_fault("live", cause, cell.id, cell.maintenance_fault_us.load(Ordering::SeqCst))),
            RuntimeMaintenanceStatus::Ready => {
                let generation = cell
                    .maintenance_generation
                    .try_update(Ordering::SeqCst, Ordering::SeqCst, |generation| generation.checked_add(1))
                    .map_err(|_| plugin_internal_fault(format!("runtime live cleanup generation exhausted for instance {}", cell.id)))?
                    .checked_add(1)
                    .expect("checked maintenance generation");
                if cell.maintenance_status.compare_exchange(RuntimeMaintenanceStatus::Ready.repr(), RuntimeMaintenanceStatus::Queued.repr(), Ordering::SeqCst, Ordering::SeqCst).is_err() {
                    return Ok(false);
                }
                let scheduled_cell = std::sync::Arc::downgrade(&cell);
                let job: semio_framework_async::Job = Box::new(move || {
                    let Some(scheduled_cell) = scheduled_cell.upgrade() else { return };
                    run_runtime_live_cleanup_turn(&scheduled_cell, semio_framework_job::Generation(generation));
                });
                let pool = runtime_close_pool();
                match pool.try_submit(semio_framework_async::Lane::Maintenance, job) {
                    Ok(()) => {
                        #[cfg(target_arch = "wasm32")]
                        pump_runtime_live_cooperative_turn(&cell)?;
                        Ok(true)
                    }
                    Err(error) => {
                        cell.maintenance_status.compare_exchange(RuntimeMaintenanceStatus::Queued.repr(), RuntimeMaintenanceStatus::Ready.repr(), Ordering::SeqCst, Ordering::SeqCst).ok();
                        drop(error.into_job());
                        Ok(false)
                    }
                }
            }
            RuntimeMaintenanceStatus::Queued | RuntimeMaintenanceStatus::Running => {
                #[cfg(target_arch = "wasm32")]
                pump_runtime_live_cooperative_turn(&cell)?;
                Ok(true)
            }
        }
    }

    // 🚫️async: E1-adjacent pure lookup consumed by `with_instances_mut`'s sync callback
    // (`FnOnce(&mut Vec<AppInstance>) -> Result<R, Fault>`, itself required sync by the
    // single-threaded `RefCell::borrow_mut` reentrancy guard) — see R9.
    fn find_instance<'a, PA: PluginApp>(list: &'a RuntimeInstanceRegistry<std::sync::Arc<RuntimeAppCell<PA>>>, instance_id: u32) -> Result<std::sync::MutexGuard<'a, AppInstance<PA>>, Fault> {
        let cell = list.get(instance_id).ok_or_else(|| plugin_internal_fault(format!("unknown instance: {instance_id}")))?;
        cell.instance.try_lock().map_err(|_| plugin_internal_fault(format!("instance busy or poisoned: {instance_id}")))
    }

    fn runtime_instance_cell<PA: PluginApp>(runtime: &PluginRuntime<PA>, instance_id: u32) -> Result<std::sync::Arc<RuntimeAppCell<PA>>, Fault> {
        runtime.instances.try_borrow().map_err(|_| plugin_internal_fault("runtime instance authority is busy"))?.get(instance_id).cloned().ok_or_else(|| plugin_internal_fault(format!("unknown instance: {instance_id}")))
    }

    async fn live_tool_identity<PA: PluginApp>(runtime: &PluginRuntime<PA>, instance_id: u32) -> Result<(String, crate::app::ToolOwnerWitness, Vec<crate::app::ArtifactToolPublicContract>), Fault> {
        with_instances_mut(runtime, |list| {
            let instance = find_instance(list, instance_id)?;
            Ok((resolve_ready(instance.app.app_id()).to_string(), resolve_ready(instance.app.tool_owner_witness()), resolve_ready(instance.app.tool_public_contracts())))
        })
        .await
    }

    /// 📏️ The ONE public invocation envelope, read off the language-neutral contract
    /// (`🛂️manifest/🎛️public-invocation/🧬️schema/🔣️.json`). `MAX_PUBLIC_ACTION_STRING_BYTES` is
    /// checked BEFORE the addressed tool's own `max_raw_wire_bytes`, so no tool contract can widen
    /// it. `setContributions` is the host pack crossing: it keeps the body cap and skips the per-string
    /// cap so one scoped contributions pack can land without 4 KiB paging
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END).
    const MAX_PUBLIC_ACTION_BODY_BYTES: usize = semio_framework::PUBLIC_INVOCATION_BODY_BYTES;
    const MAX_PUBLIC_ACTION_STRING_BYTES: usize = semio_framework::PUBLIC_INVOCATION_STRING_BYTES;
    const MAX_PUBLIC_ACTION_DEPTH: usize = semio_framework::PUBLIC_INVOCATION_DEPTH;
    const HOST_CONTRIBUTIONS_PACK_COMMAND_ID: &str = "setContributions";

    fn dff_interactive_wire_limit(owner: crate::app::ToolOwnerWitness, runtime_controller_id: &str, addressed_controller_id: &str, command_id: &str, app_contracts: &[crate::app::ArtifactToolPublicContract]) -> Result<Option<usize>, Fault> {
        let registration = app_contracts.iter().find(|registration| registration.controller_id == addressed_controller_id && registration.tool_id == command_id);
        match registration {
            Some(registration) if runtime_controller_id == addressed_controller_id && registration.owner == owner && !registration.schema_id.is_empty() => Ok(Some(registration.max_raw_wire_bytes)),
            Some(_) => Err(plugin_internal_fault("addressed app-owned tool is not owned by the live app type/controller")),
            None => Ok(None),
        }
    }

    fn dff_invocation_wire_limit(body: &str, identifier_key: &str, label: &str, owner: crate::app::ToolOwnerWitness, runtime_controller_id: &str, app_contracts: &[crate::app::ArtifactToolPublicContract]) -> Result<Option<usize>, Fault> {
        let bytes = body.as_bytes();
        let mut cursor = 0usize;
        let mut depth = 0usize;
        let mut address_depth = None;
        let mut pending_address_start = None;
        let mut identifier_seen = false;
        let mut controller_seen = false;
        let mut selected_identifier = None;
        let mut selected_controller = None;
        while cursor < bytes.len() {
            match bytes[cursor] {
                b'{' => {
                    depth = depth.saturating_add(1);
                    if pending_address_start == Some(cursor) {
                        address_depth = Some(depth);
                        pending_address_start = None;
                    }
                    cursor += 1;
                }
                b'}' => {
                    if address_depth == Some(depth) {
                        address_depth = None;
                    }
                    depth = depth.saturating_sub(1);
                    cursor += 1;
                }
                b'"' => {
                    let key_start = cursor + 1;
                    cursor = key_start;
                    let mut escaped = false;
                    while cursor < bytes.len() && bytes[cursor] != b'"' {
                        if bytes[cursor] == b'\\' {
                            escaped = true;
                            cursor = cursor.saturating_add(1);
                        }
                        cursor = cursor.saturating_add(1);
                    }
                    if cursor >= bytes.len() {
                        return Err(plugin_internal_fault(format!("{label} contains an unterminated string")));
                    }
                    let key_end = cursor;
                    cursor += 1;
                    let mut value_cursor = cursor;
                    while value_cursor < bytes.len() && bytes[value_cursor].is_ascii_whitespace() {
                        value_cursor += 1;
                    }
                    if bytes.get(value_cursor) != Some(&b':') {
                        continue;
                    }
                    if escaped && (depth == 1 || address_depth.is_some_and(|start| depth >= start)) {
                        return Err(plugin_internal_fault(format!("{label} address keys must be plain bounded identifiers")));
                    }
                    value_cursor += 1;
                    while value_cursor < bytes.len() && bytes[value_cursor].is_ascii_whitespace() {
                        value_cursor += 1;
                    }
                    let key = &body[key_start..key_end];
                    if depth == 1 && key == "address" {
                        if bytes.get(value_cursor) != Some(&b'{') {
                            return Err(plugin_internal_fault(format!("{label} address must be an object")));
                        }
                        pending_address_start = Some(value_cursor);
                    } else if address_depth == Some(depth) && key == identifier_key {
                        if identifier_seen {
                            return Err(plugin_internal_fault(format!("{label} address contains a duplicate {identifier_key}")));
                        }
                        identifier_seen = true;
                        if bytes.get(value_cursor) != Some(&b'"') {
                            return Err(plugin_internal_fault(format!("{identifier_key} must be a plain bounded string")));
                        }
                        let value_start = value_cursor + 1;
                        value_cursor = value_start;
                        let mut value_escaped = false;
                        while value_cursor < bytes.len() && bytes[value_cursor] != b'"' {
                            if bytes[value_cursor] == b'\\' {
                                value_escaped = true;
                                value_cursor = value_cursor.saturating_add(1);
                            }
                            value_cursor = value_cursor.saturating_add(1);
                        }
                        if value_cursor >= bytes.len() || value_escaped {
                            return Err(plugin_internal_fault(format!("{identifier_key} must be an unescaped bounded identifier")));
                        }
                        selected_identifier = Some(&body[value_start..value_cursor]);
                    } else if address_depth.is_some_and(|start| depth >= start) && key == "appId" {
                        if controller_seen {
                            return Err(plugin_internal_fault(format!("{label} address contains a duplicate appId")));
                        }
                        controller_seen = true;
                        if bytes.get(value_cursor) != Some(&b'"') {
                            return Err(plugin_internal_fault("appId must be a plain bounded string"));
                        }
                        let value_start = value_cursor + 1;
                        value_cursor = value_start;
                        let mut value_escaped = false;
                        while value_cursor < bytes.len() && bytes[value_cursor] != b'"' {
                            if bytes[value_cursor] == b'\\' {
                                value_escaped = true;
                                value_cursor = value_cursor.saturating_add(1);
                            }
                            value_cursor = value_cursor.saturating_add(1);
                        }
                        if value_cursor >= bytes.len() || value_escaped {
                            return Err(plugin_internal_fault("appId must be an unescaped bounded identifier"));
                        }
                        selected_controller = Some(&body[value_start..value_cursor]);
                    }
                }
                _ => cursor += 1,
            }
        }
        match selected_controller.zip(selected_identifier) {
            Some((addressed_controller_id, command_id)) => dff_interactive_wire_limit(owner, runtime_controller_id, addressed_controller_id, command_id, app_contracts),
            None => Ok(None),
        }
    }

    fn public_address_command_id(body: &str) -> Option<String> {
        serde_json::from_str::<serde_json::Value>(body).ok()?.get("address")?.get("commandId")?.as_str().map(str::to_owned)
    }

    fn validate_public_json_envelope(body: &str, label: &str) -> Result<(), Fault> {
        validate_public_json_envelope_with(body, label, true)
    }

    fn validate_public_command_json(body: &str) -> Result<(), Fault> {
        let cap_strings = public_address_command_id(body).as_deref() != Some(HOST_CONTRIBUTIONS_PACK_COMMAND_ID);
        validate_public_json_envelope_with(body, "command", cap_strings)
    }

    fn validate_public_json_envelope_with(body: &str, label: &str, cap_strings: bool) -> Result<(), Fault> {
        if body.len() > MAX_PUBLIC_ACTION_BODY_BYTES {
            return Err(plugin_internal_fault(format!("{label} exceeds the bounded public action body")));
        }
        let mut depth = 0usize;
        let mut string_bytes = 0usize;
        let mut in_string = false;
        let mut escaped = false;
        for byte in body.bytes() {
            if in_string {
                if escaped {
                    escaped = false;
                    string_bytes = string_bytes.saturating_add(1);
                } else if byte == b'\\' {
                    escaped = true;
                } else if byte == b'"' {
                    in_string = false;
                } else {
                    string_bytes = string_bytes.saturating_add(1);
                }
                if cap_strings && string_bytes > MAX_PUBLIC_ACTION_STRING_BYTES {
                    return Err(plugin_internal_fault(format!("{label} contains an oversized string")));
                }
                continue;
            }
            match byte {
                b'"' => {
                    in_string = true;
                    string_bytes = 0;
                }
                b'{' | b'[' => {
                    depth = depth.saturating_add(1);
                    if depth > MAX_PUBLIC_ACTION_DEPTH {
                        return Err(plugin_internal_fault(format!("{label} exceeds the bounded nesting depth")));
                    }
                }
                b'}' | b']' if depth == 0 => return Err(plugin_internal_fault(format!("{label} closes outside its envelope"))),
                b'}' | b']' => depth -= 1,
                _ => {}
            }
        }
        if in_string || escaped || depth != 0 {
            return Err(plugin_internal_fault(format!("{label} is structurally incomplete")));
        }
        Ok(())
    }

    fn validate_public_action_envelope(body: &str, owner: crate::app::ToolOwnerWitness, runtime_controller_id: &str, app_contracts: &[crate::app::ArtifactToolPublicContract]) -> Result<(), Fault> {
        validate_public_json_envelope(body, "action")?;
        if let Some(limit) = dff_invocation_wire_limit(body, "actionId", "action", owner, runtime_controller_id, app_contracts)? {
            if body.len() > limit {
                return Err(plugin_internal_fault("interactive Draw/Flow/Forms action exceeds its command-specific wire bound"));
            }
        }
        Ok(())
    }

    fn validate_public_command_envelope(body: &str, owner: crate::app::ToolOwnerWitness, runtime_controller_id: &str, app_contracts: &[crate::app::ArtifactToolPublicContract]) -> Result<(), Fault> {
        validate_public_command_json(body)?;
        if let Some(limit) = dff_invocation_wire_limit(body, "commandId", "command", owner, runtime_controller_id, app_contracts)? {
            if body.len() > limit {
                return Err(plugin_internal_fault("interactive Draw/Flow/Forms command exceeds its command-specific wire bound"));
            }
        }
        Ok(())
    }

    #[cfg(test)]
    include!("🧪️tests/🔬️plugin-runtime-dff-public-action-admission/🦀️.rs");

    fn addressed_action_view(view: &ViewModel, invocation: &ManifestActionInvocation) -> Result<ViewModel, Fault> {
        let projected = view.for_window_instance(&invocation.address.window_instance_id).ok_or_else(|| plugin_internal_fault(format!("unknown action window instance {}", invocation.address.window_instance_id)))?;
        if projected.active_window_kind_id.as_deref() != Some(invocation.address.window_kind_id.as_str()) {
            return Err(plugin_internal_fault(format!("action window instance {} has a different kind than {}", invocation.address.window_instance_id, invocation.address.window_kind_id)));
        }
        Ok(projected)
    }

    fn debug_action_dispatch_branch(action_id: &str) -> &'static str {
        if !crate::app::is_framework_reserved_action_id(action_id) {
            "catalog"
        } else if matches!(action_id, "copy" | "cut" | "paste") {
            "clipboard-instack"
        } else {
            "spawn-admit"
        }
    }

    /// 🎯️ Window projection for a catalog action, or the unprojected view for a framework-reserved verb.
    /// Actor ingress (`AppCommand::Command`) and `plugin_handle_action` share this rule so undo/redo
    /// reach `dispatch_framework_reserved_action` when the chrome addresses a window that does not
    /// declare the verb (or is absent from `window_instances`).
    pub(crate) fn admit_addressed_action_view(view: &ViewModel, invocation: &ManifestActionInvocation) -> Result<ViewModel, Fault> {
        match addressed_action_view(view, invocation) {
            Ok(projected) => Ok(projected),
            Err(_) if crate::app::is_framework_reserved_action_id(&invocation.address.action_id) => Ok(view.clone()),
            Err(fault) => Err(fault),
        }
    }

    #[expect(clippy::await_holding_lock, reason = "This local future retains exclusive app ownership while suspended; competing production instance access uses try_lock and refuses or yields instead of waiting.")]
    pub async fn plugin_handle_action<PA: PluginApp>(runtime: &PluginRuntime<PA>, instance_id: u32, action_json: &str, context_json: &str) -> Result<InvocationResult, Fault> {
        debug_runtime_line(format_args!("[DEBUG] plugin_handle_action entry instance={instance_id}"));
        validate_public_json_envelope(action_json, "action")?;
        let (runtime_controller_id, owner, app_contracts) = live_tool_identity(runtime, instance_id).await?;
        validate_public_action_envelope(action_json, owner, &runtime_controller_id, &app_contracts)?;
        validate_public_json_envelope(context_json, "action context")?;
        let invocation: ManifestActionInvocation = dsl::os_pack::json::from_json_str(action_json).map_err(|error| plugin_internal_fault(error.to_string()))?;
        debug_runtime_line(format_args!("[DEBUG] plugin_handle_action actionId={} branch={}", invocation.address.action_id, debug_action_dispatch_branch(&invocation.address.action_id)));
        let context: Value = serde_json::from_str(context_json).map_err(|error| plugin_internal_fault(error.to_string()))?;
        let actor = context.get("actor").and_then(|value| value.as_str()).unwrap_or("local").to_string();
        let owner_matches = runtime.plugin.borrow().as_ref().is_some_and(|program| program.manifest.plugin_id == invocation.address.plugin_id);
        if !owner_matches {
            return Err(plugin_internal_fault(format!("action plugin owner {} does not match the active program", invocation.address.plugin_id)));
        }
        let view = context.get("viewState").cloned().and_then(|value| serde_json::from_value::<ViewModel>(value).ok()).ok_or_else(|| plugin_internal_fault("action context is missing a valid viewState"))?;
        let view = admit_addressed_action_view(&view, &invocation)?;
        let active_mode_id = view.active_mode_id.clone();
        let meta = ActionMeta { actor, instance_id, view_state: Some(view) };
        let cell = runtime_instance_cell(runtime, instance_id)?;
        let mut instance = cell.instance.try_lock().map_err(|_| plugin_internal_fault(format!("instance busy or poisoned: {instance_id}")))?;
        instance.surface_contexts.update_view(meta.view_state.as_ref().expect("addressed UI action has host context"));
        drive_self_waking_ready(instance.app.handle_action_invocation(&invocation, active_mode_id.as_deref(), &meta))
    }

    /// @emoji 🎛️ Dispatches a structurally addressed command to its actual owner. Plugin commands
    /// execute on the program registry; app/mode commands execute on the addressed app instance, with
    /// active-mode gating for mode ownership. OS commands never enter a plugin runtime.
    pub async fn plugin_handle_command<PA: PluginApp>(runtime: &PluginRuntime<PA>, instance_id: u32, command_json: &str, context_json: &str) -> Result<InvocationResult, Fault> {
        validate_public_command_json(command_json)?;
        let (runtime_controller_id, owner, app_contracts) = live_tool_identity(runtime, instance_id).await?;
        validate_public_command_envelope(command_json, owner, &runtime_controller_id, &app_contracts)?;
        validate_public_json_envelope(context_json, "command context")?;
        let invocation: ManifestCommandInvocation = dsl::os_pack::json::from_json_str(command_json).map_err(|error| plugin_internal_fault(error.to_string()))?;
        let context: Value = serde_json::from_str(context_json).map_err(|error| plugin_internal_fault(error.to_string()))?;
        let actor = context.get("actor").and_then(|value| value.as_str()).unwrap_or("local").to_string();
        let view_state = context.get("viewState").cloned().map(serde_json::from_value::<ViewModel>).transpose().map_err(|error| plugin_internal_fault(error.to_string()))?;
        let meta = ActionMeta { actor, instance_id, view_state };
        match &invocation.address.owner {
            ManifestCommandOwnerAddress::Os => Err(plugin_internal_fault("os commands must be dispatched by the os host")),
            // 🌉️ `LocalKey::with`'s closure is sync — bridged via `resolve_ready` (`handle_plugin_command`
            // dispatches to a plain sync `PluginCommandHandler` closure internally, no real suspension).
            ManifestCommandOwnerAddress::Plugin { .. } => {
                let program = runtime.plugin.borrow();
                let program = program.as_ref().ok_or_else(|| plugin_internal_fault("plugin not initialized"))?;
                program.handle_plugin_command(&invocation, &meta)
            }
            ManifestCommandOwnerAddress::App { plugin_id, .. } | ManifestCommandOwnerAddress::Mode { plugin_id, .. } => {
                let owner_matches = runtime.plugin.borrow().as_ref().is_some_and(|program| program.manifest.plugin_id == *plugin_id);
                if !owner_matches {
                    return Err(plugin_internal_fault(format!("command plugin owner {plugin_id} does not match the active program")));
                }
                let active_mode_id = meta.view_state.as_ref().ok_or_else(|| plugin_internal_fault("app command context is missing viewState"))?.active_mode_id.as_deref();
                with_instances_mut(runtime, |list| {
                    let mut instance = find_instance(list, instance_id)?;
                    if let Some(view) = &meta.view_state {
                        instance.surface_contexts.update_view(view);
                    }
                    resolve_ready(instance.app.handle_command(&invocation, active_mode_id, &meta))
                })
                .await
            }
        }
    }

    /// @emoji 📥️ Ingests binary-encoded remote `MutationEnvelope`s (`protocol::decode_envelopes`) into
    /// the instance's document store (idempotent — duplicate mutation ids are dropped by the causal
    /// DAG / edit-id dedupe), returning one `protocol::MergeReport` per envelope for the caller
    /// (`ApplyEnvelopes`'s handler) to frame as unsolicited `AppFrame::MergeReport` frames.
    pub async fn plugin_ingest_operations<PA: PluginApp>(runtime: &PluginRuntime<PA>, instance_id: u32, mutations: &[u8]) -> Result<Vec<protocol::MergeReport>, Fault> {
        with_instances_mut(runtime, |list| {
            let mut instance = find_instance(list, instance_id)?;
            resolve_ready(instance.app.ingest_operations(mutations))
        })
        .await
    }

